MultiLanguageItemData['it'][199892] = {name = "[q3]Pentolone di Zuppa da Viaggio dei Tuskarr", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Aumenta l'indice di versatilità dei compagni vicini di 1 e permette di cucinare. (5 Min Recupero)\nRichiede il livello di Fama 4 con i Tuskarr di Iskaara."}
MultiLanguageItemData['it'][199893] = {name = "[q3]Frammenti di Pietra Preziosa", additional_info = "Si vincola alla raccolta\nQuesto oggetto avvia una missione\n[q]\"Frammenti di una gemma infranta per un castone di un gioiello più grande.\""}
MultiLanguageItemData['it'][199894] = {name = "[q3]Follia del Pescatore", additional_info = "Si vincola alla raccolta\nGiocattolo\nUsa: Posizioni il cestino della Follia del Pescatore sul terreno per sfidare i tuoi amici e vedere chi pesca il piccolo pesce. (1 Min Recupero)\nRichiede il livello di Fama 17 con i Tuskarr di Iskaara."}
MultiLanguageItemData['it'][199895] = {name = "[q3]Pezzo di Scultura", additional_info = "Si vincola alla raccolta\nQuesto oggetto avvia una missione\n[q]\"Un grosso pezzo di scultura... di un soggetto sconosciuto.\""}
MultiLanguageItemData['it'][199896] = {name = "[q3]Testa di Pesce Gommosa", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Evoca una Testa di Pesce Gommosa sulla posizione bersaglio per 5 min. La testa di pesce funge da manichino d'allenamento.\n\n Utilizzabile solo all'esterno. (1 Ora Recupero)\nRichiede il livello di Fama 17 con i Tuskarr di Iskaara.[q]\"Un sottoprodotto molto resistente, ma attenzione all'odore.\""}
MultiLanguageItemData['it'][199897] = {name = "[q3]Poltrona a Sacco Coperta di Blu", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Posizioni la poltrona a sacco ai tuoi piedi. (5 Min Recupero)\nRichiede il livello di Fama 23 con i Tuskarr di Iskaara.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][199899] = {name = "[q3]Slittino di Iskaara", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Trascini uno slittino per bambini dei Tuskarr su cui può sedersi chiunque.\nRichiede il livello di Fama 26 con i Tuskarr di Iskaara. Richiede il livello di Fama 27 con i Tuskarr di Iskaara.[q]\"Tra i Tuskarr si dice che colui che trascina lo slittino di un altro è un pilastro della comunità. Ma questo non impedisce ai bambini di litigare per chi può farsi trascinare.\""}
MultiLanguageItemData['it'][199900] = {name = "[q3]Attrezzi per Rilevamenti di Seconda Mano", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Prepari l'equipaggiamento di rilevamento, così che sembri che stai facendo qualcosa di molto importante. (30 Min Recupero)\n[q]\"Ottimi per far sembrare che si stia davvero facendo qualcosa.\"\nPrezzo di vendita:"}
