MultiLanguageItemData['it'][199928] = {name = "Torcia Lanciafiamme", additional_info = "Oggetto di missione\nUnico\n[q2]Usa: Usa la Torcia Lanciafiamme per infliggere 88219 danni da fuoco ogni 0.3 s in 6 sec. (8 S Recupero)\n[q]\"Incantata dagli elementi dell'aria e del fuoco, questa torcia farà bene il suo lavoro. Tenere lontana dalla faccia.\""}
