MultiLanguageItemData['it'][200085] = {name = "[q3]Fili di Khaz'gorite", additional_info = "Materiale per Equipaggiamento da Pesca di Iskaara\n[q7]Si vincola alla Brigata\n\"Utilizzabile per migliorare ulteriormente la Rete da Pesca di Iskaara. Da portare a Tavio a Iskaara. Si può trovare dentro una rete da pesca.\""}
MultiLanguageItemData['it'][200086] = {name = "[q3]Resina Infusa di Khaz'gorite", additional_info = "Materiale per Equipaggiamento da Pesca di Iskaara\n[q7]Si vincola alla Brigata\n[q]\"Utilizzabile per migliorare ulteriormente l'Arpione di Iskaara. Da portare a Tavio a Iskaara. Ottenibile dai pesci GRANDI delle Isole dei Draghi con l'Arpione di Iskaara.\""}
