MultiLanguageItemData['it'][200115] = {name = "Sarantuya il Veritiero", additional_info = "Oggetto di missione\n[q]\"Per la luce lunare, gli assassini sono stati mandati per Maruuk. Per la luce lunare, Teera li ha uccisi prima.\""}
MultiLanguageItemData['it'][200116] = {name = "[q3]Corno Perpetuo di Lava", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Bevi da questo corno per diventare immune alla lava all'esterno sulle Isole dei Draghi per 10 minuti. (30 Min Recupero)\n[q]\"Aiuta a nuotare nella lava. Da togliere solo se non si sta nuotando.\""}
MultiLanguageItemData['it'][200117] = {name = "Cinturone Dorato del Guardiano", additional_info = "Oggetto di missione\nUnico\n[q]\"Contiene molti potenziali segreti dei Titani, sulla lavorazione del metallo e, soprattutto, sulla moda.\""}
MultiLanguageItemData['it'][200118] = {name = "[q4]Lontruk da Ricognizione Gialla", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 25 con i Tuskarr di Iskaara.\n\n\n[q]\"Le lontruk gialle da esplorazione amano nascondersi e riescono a mimetizzarsi bene nell'ambiente circostante. Quando non giocano a \"nascondino\" con i loro cavalieri, sono compagne perfette per perlustrare accampamenti nemici.\"\nFazione:\nTuskarr di Iskaara\nFama:\n25\nMercante:\nTatto\nPosizione:\nIskaara\nCosto:\n2\n2\n750"}
MultiLanguageItemData['it'][200119] = {name = "Fiammacuore Ardente", additional_info = "Oggetto di missione\nUnico\n[q]\"Dicono che il cuore di Firava sia cresciuto del triplo quel giorno, grazie ai Primalisti.\""}
MultiLanguageItemData['it'][200120] = {name = "[q4]Nucleo Energetico di Irideus", additional_info = "Oggetto di missione\n[q2]Usa: Sintonizza il Nucleo Energetico su un personaggio titanico d'élite del Forte di Tyr, indebolendolo.\n[q]\"Recuperato dalle Sale dell'Infusione, questo dispositivo un tempo alimentava il Guardiano Irideus. Ora deve essere sintonizzato nuovamente per riottenere il suo potere originale.\""}
MultiLanguageItemData['it'][200121] = {name = "Pozione della Fortuna del Principiante", additional_info = "[q2]Usa: Fornisce +1 Fortuna.\n[q]\"Ce la puoi fare!\""}
MultiLanguageItemData['it'][200122] = {name = "Cannocchiale Temporale", additional_info = "Oggetto di missione\nUnico\n[q]\"Scintille di cose passate, presenti e future si sovrappongono man mano che lo guardi.\""}
MultiLanguageItemData['it'][200123] = {name = "Giglio Torrenziale", additional_info = "Oggetto di missione\nUnico\n[q]\"Gocce d'acqua magica si formano sui petali e galleggiano verso l'alto in una spirale.\""}
MultiLanguageItemData['it'][200124] = {name = "Codino Disorientato", additional_info = "Oggetto di missione\nUnico\n[q]\"Le leggende dicono che questo pesce raro ha la capacità di esaudire i desideri di coloro che lo catturano.\""}
