MultiLanguageItemData['it'][200549] = {name = "[q3]Manufatto dei Titani Restaurato", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+244 Intelletto\n[q2]Usa: Protegge un alleato con uno scudo che assorbe massimo 37740 danni subiti da una grande distanza e aumentando la velocità di movimento di massimo 5726 . Lo scudo e il bonus alla velocità di movimento variano in base alla distanza dal bersaglio: quanto più si è vicini, tanto più lo scudo aumenta e il bonus alla velocità diminuisce. (1 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][200550] = {name = "[q3]Pelliccia Molto Comoda", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Un po' di relax, in pieno stile Maruuk! (20 Min Recupero)\nRichiede il livello di Fama 3 con i Centauri Maruuk e il completamento della missione \"Scambio culturale\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][200551] = {name = "[q3]Pila di Pelli Confortevoli", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Riposa come una Khanam ovunque tu vada! (20 Min Recupero)\nRichiede il livello di Fama 3 con i Centauri Maruuk e il completamento della missione \"Scambio culturale\".\nPrezzo di vendita:"}
MultiLanguageItemData['it'][200552] = {name = "[q3]Guscio dell'Invocatore del Torrente", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+244 Forza\n[q2]Usa: Incanala le fiamme tutt'intorno, infliggendo [ 1906 * (6) * (1 + Versatility)] danni da natura ai nemici vicini in 3 sec. Poi, scatena una potente esplosione che infligge 53355 danni da natura suddivisi tra tutti i nemici vicini. (2 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][200553] = {name = "Nettare di Pantis", additional_info = "Rifornimenti delle Isole dei Draghi\nSi vincola alla raccolta\n[q2]Aggiunge il Nettare di Pantis ai Rifornimenti delle Isole dei Draghi.\n[q]\"Il fiore a forma di ciotola crea un pozzo per il nettare. Ricco di zuccheri, il nettare è molto richiesto come ingrediente per cucinare.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][200554] = {name = "Testa di Gorcino", additional_info = "Rifornimenti delle Isole dei Draghi\nSi vincola alla raccolta\n[q2]Aggiunge la Testa di Gorcino Oleoso ai Rifornimenti delle Isole dei Draghi.\n[q]\"Il gorcino rilascia un olio, quando matura, molto apprezzato come acceleratore del fuoco.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][200555] = {name = "Semi Infernali", additional_info = "Rifornimenti delle Isole dei Draghi\nSi vincola alla raccolta\n[q2]Aggiunge i Semi Infernali ai Rifornimenti delle Isole dei Draghi.\n[q]\"Simili ai granelli della polvere da sparo, i baccelli infernali esplodono quando sbocciano, sparpagliando i semi. I Djaradin li raccolgono mentre fioriscono e li usano nelle loro fucine a temperature prossime alla fusione.\"\nPrezzo di vendita:"}
