MultiLanguageItemData['it'][201425] = {name = "[q4]Lontruk da Guerra Gialla", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 30 con i Tuskarr di Iskaara.\n\n\n[q]\"Le lontruk gialle della Vastità Azzurra sono eleganti, subdole e astute. Quelle addestrate alla guerra sono tra le migliori cavalcature dei Tuskarr, ugualmente capaci a terra e in acqua.\"\nFazione:\nTuskarr di Iskaara\nFama:\n30\nMercante:\nTatto\nPosizione:\nIskaara\nCosto:\n5\n5\n1.000"}
MultiLanguageItemData['it'][201426] = {name = "[q4]Lontruk da Guerra Marrone", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 30 con i Tuskarr di Iskaara.\n\n\n[q]\"I Tuskarr di Iskaara rifiutano di farsi la guerra gli uni con gli altri, ma molti di loro, nonché i loro alleati, hanno ciò nonostante impugnato la lancia al fianco di una lontruk da guerra.\"\nFazione:\nTuskarr di Iskaara\nFama:\n30\nMercante:\nTatto\nPosizione:\nIskaara\nCosto:\n5\n5\n1.000"}
MultiLanguageItemData['it'][201427] = {name = "Sabbie Sfuggenti", additional_info = "Si vincola alla raccolta\nUnico (20)\n[q2]Usa: Una spruzzata rinvigorente di magia del tempo!\n\n Aumenta la velocità di movimento del 250% per 5 sec. (30 S Recupero)\nPrezzo di vendita:"}
