MultiLanguageItemData['it'][202610] = {name = "[q4]Distributore di Bombe di Dragonfuoco", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+473 Agilità\n[q2]Usa: Attacca una Bomba di Dragonfuoco sul bersaglio, infliggendo 38559 danni da fuoco dopo 7 sec. Se il bersaglio muore con una bomba attaccata, infligge 32132 danni suddivisi tra tutti i nemici entro 10 m. È possibile accumulare un massimo di 3 bombe. (30 s di recupero)\n\n Dopo aver inferto 60 colpi critici, si attiva un lampo d'ispirazione, che permette di assemblare una carica di bomba aggiuntiva all'istante. (5 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][202611] = {name = "10.1 Raid - Black Dragon Labs - Boss <#> -", additional_info = "[q4]10.1 Raid - Black Dragon Labs - Boss <#> - - Accessory - Trinket - Physical DPS\nSi vincola alla raccolta\nUnico equipaggiabile\nMonile\n+447 [Agilità o Forza]\nPrezzo di vendita:"}
MultiLanguageItemData['it'][202612] = {name = "[q4]Scaglia di Drago Nero Urlante", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+473 [Agilità o Forza o Intelletto]\n[q2]Equipaggia: Gli attacchi e le abilità hanno una probabilità di fornire delle ali di drago effimere, aumentando l'indice di critico di 1022 e l'indice di ritorno vitale di 285 per 15 sec. (15s di recupero)\n[q2]Usa: Richiama un'eco del potere di Neltharion che colpisce il suolo, infliggendo 24246 danni da ombrofuoco ai nemici vicini se ci si è spostati di almeno 15 m. (3 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][202613] = {name = "[q4]Ancora del Caos degli Zaqali", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+447 Forza\n[q2]Usa: Lancia il rampino fino a 20 m di distanza per impalare il bersaglio, infliggendo 61039 danni fisici e permettendo di scagliarsi contro il bersaglio con forza tremenda. All'impatto, infligge 83082 danni vulcanici suddivisi tra tutti i nemici vicini.\n\n I danni inflitti all'impatto aumentano per ogni nemico colpito, fino a un massimo di 5 nemici. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][202614] = {name = "[q4]Cuore Fuso di Rashok", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+460 Intelletto\n[q2]Equipaggia: Gli incantesimi di cura hanno una probabilità di risvegliare il Cuore, rigenerando [ 146 * (10)] mana in 10 sec e aumentando la salute rigenerata dagli incantesimi di cura di [ 1491 * (10)] in 10 sec.\n\n Le sovracure fornite da questo effetto rinvigoriscono il bersaglio, aumentandone l'indice di versatilità di massimo 380 per 12 sec. (10s di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][202615] = {name = "[q4]Ricettacolo delle Ombre Roventi", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+447 Intelletto\n[q2]Equipaggia: Gli incantesimi d'attacco hanno un'alta probabilità di attirare Fiamme Instabili dal Ricettacolo, aumentando l'indice di celerità di 90 e infliggendo ( 133 * 30 / 3) danni da fuoco in 30 sec.\n\n Al raggiungimento di 5 accumuli, le fiamme balzano verso il bersaglio, infliggendo 29019 danni da ombra istantaneamente e ( 7255 * 6) danni da ombrofuoco aggiuntivi in 12 s.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][202616] = {name = "[q4]Piastre Oscure Resistenti", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+447 [Agilità o Forza]\n[q2]Usa: La copertura di 5 Piastre d'Inferacciaio riduce i danni subiti di 5320 e la velocità di movimento del 3 % per piastra per 15 sec.\n\n Subire 44323 danni spacca una piastra, rimuovendola e scatenando un pilastro d'ombrofuoco che infligge 19593 danni da ombrofuoco a tutti i nemici sulla traiettoria. L'effetto può verificarsi solo una volta ogni 2 s. Al termine, le piastre restanti si spezzano. (2s di recupero) (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][202617] = {name = "[q4]Incudine da Tasca d'Elementio", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+447 [Agilità o Forza]\n[q2]Equipaggia: Affila la tua arma con l'elementio, fornendo [all'abilità di classe principale della specializzazione da assaltatore in mischia] una probabilità di infliggere ( 37814 * 0.6) danni da ombrofuoco aggiuntivi all'impatto.\n[q2]Usa: Colpisce l'incudine con l'arma per rafforzarla, infliggendo 7221 danni da ombrofuoco ai nemici vicini e aumentando i danni inflitti all'impatto del 33 % fino a qualche istante dopo il termine del combattimento. Si accumula fino a 5 volte. (1 Min Recupero)\nPrezzo di vendita:"}
