MultiLanguageItemData['it'][202698] = {name = "La Voce Dragoide 4: Potere e diritti", additional_info = "Oggetto di missione\n[q]\"I draghi ci goveRnavano, come con i DracthYr, perché erano più forti di noi. Ma insieme, con i nostri numeri, noi siamo più forti di loro. Se la ragione è dove sta la forza, allora abbiamo ragione, se abbiamo anche il coraggio di ribellarci. - Istigatrice Belafon\""}
MultiLanguageItemData['it'][202699] = {name = "La Voce Dragoide 2: Abbandonati per 100 secoli", additional_info = "Oggetto di missione\n[q]\"Per cento anni ci hanno lasciati soli, a occuparci delle \"loro\" isole, a custodiRe le loro città e le loro strade, a mantenere la pace. Hanno ripetuto questo abbandono 99 volte. Dovremmo accoglierli a braccia apertE, obbedire come in passato? - Istigatrice Belafon\""}
MultiLanguageItemData['it'][202700] = {name = "La Voce Dragoide 3: Indipendenti per 100 secoli", additional_info = "Oggetto di missione\n[q]\"I draghi sono tornati, aspettandosi che fossimo ciò che eravamo, ma in questi cento secoli siamo cambiati. Siamo cresciuti. Non li serViamo più e non siamo più loro servi. Abbiamo sceltO la nostra strada per 10.000 anni e continueremo a farlo. - Istigatrice Belafon\""}
MultiLanguageItemData['it'][202701] = {name = "La Voce Dragoide 5: Il codice dei ribelli", additional_info = "Oggetto di missione\n[q]\"E per questo giuriamo di essere tutt'uno con il codice dei ribelli. Nessun sovrano tranne noi stessi. Nessun DracthYr, nessun drago. Nessun obiettiVo tranne l'indipendenza. Nessuno stormo tranne i Senzavolo. - Istigatrice Belafon\""}
MultiLanguageItemData['it'][202702] = {name = "La Voce Dragoide 1: Il valore di un dragoide", additional_info = "Oggetto di missione\n[q]\"I draghi credono di valere più di noi. È Per questo che Sendrax ha doVuto sacrificare se stessa, per un uovo di drago che potrebbe essere inutilizZabile. Dicono sia un'eroina, ma in realtà è una vittima. - Istigatrice Belafon\""}
