MultiLanguageItemData['it'][204353] = {name = "[q3]Kit dell'Orefice Primordiale", additional_info = "Oggetto di missione\n[q]\"Una raccolta di attrezzi unici. Usarli con maestria richiede anni di esperienza.\""}
MultiLanguageItemData['it'][204354] = {name = "[q3]Pacco di Cibo dei Mezzorsi Svuotato", additional_info = "Cosmetico\n[q7]Si vincola alla Brigata\nSchiena\nRichiede la reputazione Onorato con i Mezzorsi Mantogelido con almeno un personaggio della tua Brigata.\n[q2]Usa: Aggiungi questo aspetto alla collezione della Brigata.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][204355] = {name = "[q3]Pacco di Cibo dei Mantogelido Svuotato", additional_info = "Cosmetico\n[q7]Si vincola alla Brigata\nSchiena\nRichiede la reputazione Riverito con i Mezzorsi Mantogelido con almeno un personaggio della tua Brigata.\n[q2]Usa: Aggiungi questo aspetto alla collezione della Brigata.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][204356] = {name = "[q2]Polvere di Gemma Illustre", additional_info = "Si vincola alla raccolta\nReagente d'artigianato\n\"Materiale acquisito grazie alla competenza in Oreficeria, frantumando le gemme di Cataclysm. Può essere comprato e venduto a Roccavento e Orgrimmar in cambio di Emblemi dell'Orefice Illustre.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][204359] = {name = "[q3]Borsellino del Corridore dell'Isola", additional_info = "Si vincola alla raccolta\n[q]\"Pieno di oro, Rifornimenti delle Isole dei Draghi e talvolta un Manoscritto del Guardadrachi.\"\n[q2]<Destra Aprire>"}
MultiLanguageItemData['it'][204360] = {name = "[q3]Globo Pietrificato Strano", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina il Globo Pietrificato Strano con un Frammento di Scaglie di Drago Nero per invertire la pietrificazione.\n[q]\"Intrappolato nelle cripte per migliaia di anni, questo oggetto è diventato duro come una roccia. Forse una potente fonte di magia della terra potrebbe ripristinarlo.\""}
MultiLanguageItemData['it'][204361] = {name = "[q4]Dracondoso Serpeggiante", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Dracondoso Serpeggiante cavalcabile.\n\n Questa cavalcatura può usare Viaggio in Compagnia.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Questi drachi si sentono a casa nelle profondità della terra e nella vastità del cielo.\"\nImpresa:\nUna scoperta serpentina"}
MultiLanguageItemData['it'][204363] = {name = "[q3]Uovo Particolarmente Ordinario", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina l'Uovo Particolarmente Ordinario con una Goccia di Magia del Drago Blu per incantarlo.\n[q]\"A quanto pare, non c'è niente di strano in quest'uovo. Forse potrebbe essere potenziato da qualcosa che si trova nelle cripte.\""}
MultiLanguageItemData['it'][204364] = {name = "[q3]Uovo Alterato Magicamente", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina l'Uovo Alterato Magicamente con alcuni Carboni di Rubino Inestinguibili per farlo schiudere.\n[q]\"Un uovo potenziato dalla misteriosa magia dei Draghi Blu. Se solo riuscissi a trovare qualcosa nelle cripte per farlo schiudere...\""}
MultiLanguageItemData['it'][204365] = {name = "Fascio di Lance d'Ebano", additional_info = "Oggetto di missione\n[q2]Usa: Piazza una Lancia d'Ebano nel cadavere di un Djaradin Zaqali. (5 S Recupero)\n[q]\"Una raccolta di lance impugnate dallo Stormo dei Draghi Neri, ancora affilate come il giorno in cui sono state forgiate.\""}
MultiLanguageItemData['it'][204366] = {name = "[q3]Uovo dal Contenuto Sconosciuto", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina l'Uovo dal Contenuto Sconosciuto con un Granello di Polvere Bronzea per farlo invecchiare.\n[q]\"L'uovo misterioso si è finalmente schiuso, ma non si riesce a capire quale creatura si trovi all'interno. Forse sarà più chiaro quando crescerà. Qualcosa nelle cripte potrebbe accelerare il processo.\""}
MultiLanguageItemData['it'][204367] = {name = "[q3]Antico Mammut Dormiente", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina l'Antico Mammut Dormiente con una Spilla del Drago di Smeraldo per risvegliarlo.\n[q]\"Dal tuo uovo è uscito un mammut? Non sembra corretto, ma non ha senso fermarsi ora. Trova un modo per svegliarlo e ottenere la tua ricompensa!\""}
MultiLanguageItemData['it'][204369] = {name = "[q3]Frammento di Scaglie di Drago Nero", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina il Globo Pietrificato Strano con un Frammento di Scaglie di Drago Nero per invertire la pietrificazione.\n[q]\"Una scintilla di magia della terra persiste all'interno di queste scaglie di Drago Nero mutate. Potrebbe essere in grado di invertire le pietrificazioni minori.\""}
MultiLanguageItemData['it'][204370] = {name = "Pozione Puzzolente Luminosa", additional_info = "Tossico\n[q2]Usa: Illumina tutto il mondo intorno.\n[q]\"Miscela due parti di sassifraga, una parte pura di decadimento e alcune misteriose spore per mantenere all'erta chi lo beve.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][204371] = {name = "[q3]Goccia di Magia del Drago Blu", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina l'Uovo Particolarmente Ordinario con una Goccia di Magia del Drago Blu per incantarlo.\n[q]\"L'immagine sulla fiala è difficile da comprendere, ma di certo è un drago. Dovrebbero valutare di cambiare le etichette.\""}
MultiLanguageItemData['it'][204372] = {name = "[q3]Granello di Polvere Bronzea", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina l'Uovo dal Contenuto Sconosciuto con un Granello di Polvere Bronzea per farlo invecchiare.\n[q]\"Nessuno nasconderebbe della polvere in una cripta piena di tesori. Probabilmente è un potente catalizzatore temporale magico dei Draghi di Bronzo. Attenzione a non usarne troppa!\""}
MultiLanguageItemData['it'][204373] = {name = "[q3]Foglio di Rumble Distrutto", additional_info = "[q7]Si vincola alla Brigata\n[q2]Usa: Dispiegalo.\n[q]\"Sistemalo.\""}
MultiLanguageItemData['it'][204374] = {name = "[q3]Spilla del Drago di Smeraldo", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina l'Antico Mammut Dormiente con una Spilla del Drago di Smeraldo per risvegliarlo.\n[q]\"Si riesce a sentire il potere del Sogno di Smeraldo nascosto all'interno. Dovrebbe risvegliare qualsiasi creatura.\""}
MultiLanguageItemData['it'][204375] = {name = "[q3]Carboni di Rubino Inestinguibili", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina l'Uovo Alterato Magicamente con alcuni Carboni di Rubino Inestinguibili per farlo schiudere.\n[q]\"Una manciata di carboni caldi al tocco. Devono provenire dal fuoco guaritore di un antico Drago Rosso. Forse possono servire a fornire cure minori.\""}
MultiLanguageItemData['it'][204377] = {name = "Spore Luminose", additional_info = "Oggetto di missione\n[q]\"Funghi luminosi che i topi hanno una particolare abilità nel rintracciare grazie all'olfatto.\""}
MultiLanguageItemData['it'][204378] = {name = "[q4]Pacco Vibrante di Kit di Forniture per la Spedizione delle Scaglie di Drago", additional_info = "[q7]Si vincola alla Brigata\n[q]\"Contiene diverse ricompense per coloro che hanno dimostrato di essere veri alleati della Spedizione delle Scaglie di Drago.\"\n[q2]<Destra Aprire>"}
