MultiLanguageItemData['it'][205204] = {name = "[q4]Alaroccia Fiammeggiante - Soggetto 01", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Alaroccia Catalogato.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il primo esemplare di alaroccia fiammeggiante mai scoperto. Nove ricercatori su dieci confermano: è caldo!\"\nZona:\nCaverna di Zaralek\nEvento pubblico:\nRicercatori Sotto Attacco"}
MultiLanguageItemData['it'][205205] = {name = "[q4]Alaroccia d'Ombrofuoco", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Nato dal magma, il suo carapace era originariamente fatto di grumi fusi di roccia vulcanica raffreddata. Essere infuso dall'ombrofuoco non ha fatto che solidificare ulteriormente la sua natura indistruttibile.\"\nImpresa:\nGloria dell'incursore dell'Aberrus"}
MultiLanguageItemData['it'][205207] = {name = "[q4]Redini della Bestia da Fiuto", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 18 con i Niffen di Loamm.\n\n\n[q]\"Una razza di alaroccia addestrati dai Niffen per trovare i bocconcini più profondi.\"\nMercante:\nHarlowe Marl\nZona:\nCaverna di Zaralek\nCosto:\n800"}
MultiLanguageItemData['it'][205208] = {name = "[q4]Alaroccia Sabbioso", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I motivi sulle ali della creatura ricordano la sabbia che scorre attraverso una clessidra. Li si potrebbe stare a fissare per anni...\"\nMercante:\nQualsiasi Mercante dei Viaggi nel Tempo\nCosto:\n5.000"}
MultiLanguageItemData['it'][205209] = {name = "[q4]Redini del Trasportamassi", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questi alaroccia sono stati addestrati per trasportare grandi quantità di Macigni per Baratto per le attività di scambio dei Niffen.\"\nMercante:\nPonzo\nZona:\nCaverna di Zaralek\nCosto:\n85"}
