MultiLanguageItemData['it'][206013] = {name = "[q3]Progetti d'Anima", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina la Tavoletta di Uroboro con i Progetti d'Anima.\n[q]\"Decorati con gli antichi simboli dell'anima e dell'aria.\""}
MultiLanguageItemData['it'][206014] = {name = "[q3]Tavoletta di Uroboro", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina la Tavoletta di Uroboro con i Progetti d'Ossa.\n[q]\"I disegni circolari mostrano un grosso schema a spirale che parte dal lato sinistro. I simboli dell'acqua e del sangue scorrono verso l'interno e negli spazi mancanti lungo il fondo.\""}
MultiLanguageItemData['it'][206015] = {name = "[q3]Tavoletta di Uroboro", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina la Tavoletta di Uroboro con i Progetti di Mente.\n[q]\"I simboli delle ossa e della terra disegnano il percorso della spirale, che continua dal basso verso l'alto e sul lato destro mancante.\""}
MultiLanguageItemData['it'][206016] = {name = "[q3]Tavoletta di Uroboro", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina la Tavoletta di Uroboro con i Progetti d'Anima.\n[q]\"I simboli della mente e del fuoco si avvolgono attorno alla spirale intagliata, muovendosi verso l'interno e finendo in cima.\""}
MultiLanguageItemData['it'][206017] = {name = "[q3]Tavoletta di Uroboro", additional_info = "Si vincola alla raccolta\n[q2]Usa: Combina la Tavoletta di Uroboro con la Scaglia Luminescente di Kob'rok.\n[q]\"I simboli dell'anima e dell'aria, disegnati con tratti delicati, decorano la cima, mentre la spirale continua verso l'interno. L'uroboro al centro brilla di un'energia viola che viene assorbita dalla spirale verso il centro.\""}
