MultiLanguageItemData['it'][206670] = {name = "[q3]Guanti di Cepposcuro", additional_info = "Si vincola alla raccolta\nUnico (20)\n[q2]Usa: Permette di indossare i Guanti di Cepposcuro sull'armatura per poter trascinare i Viticci Radicombra fuori dal terreno.\n\n I viticci si possono trovare presso il Campo Fungino e nelle zone delle Guardafiamme vicine. (5 S Recupero)\n[q]\"Guanti corazzati rinforzati per afferrare i viticci sferzanti in sicurezza.\""}
MultiLanguageItemData['it'][206671] = {name = "[q4]Alabarda del Gladiatore d'Ossidiana", additional_info = "Si vincola alla raccolta\n{Due mani} {Arma ad asta}\n{836 - 1,553 Danni} {Velocità 3.60}\n(331.8 danni per secondo)\n+441 Forza\n+1.295 Tempra\n[q2]+ 207 Celerità\n[q2]+ 517 Versatilità\nIntegrità 120 / 120\nPrezzo di vendita:"}
MultiLanguageItemData['it'][206673] = {name = "[q4]Corno del Lupo da Guerra Bianco", additional_info = "[q7]Si vincola alla Brigata\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Horde race]\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Lupo da Guerra Bianco cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"La fame di un lupo può mai essere saziata? Questi lupi brutali cercano e divorano i nemici dell'Orda.\"\nOrda\nBottino:\nFenditure del Tempo\nMercante:\nCustode Krizzik\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000\n\nAlleanza\nOggetto:\nDono del Lupo da Guerra Bianco"}
MultiLanguageItemData['it'][206674] = {name = "[q4]Redini del Grifone Nero Vorace", additional_info = "[q7]Si vincola alla Brigata\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\n[q2]Usa: Ti insegna a evocare un Grifone Nero Vorace.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"La guerra ha corrotto queste creature, un tempo orgogliose. I sussurri delle loro ali ora raccontano presagi di imminente sconfitta.\"\nAlleanza\nBottino:\nFenditure del Tempo\nMercante:\nCustode Krizzik\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000\n\nOrda\nOggetto:\nDono del Grifone Nero Vorace"}
MultiLanguageItemData['it'][206675] = {name = "[q4]Albatros dalle Zampe Dorate", additional_info = "[q7]Si vincola alla Brigata\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Arrivata volteggiando da un lontano flusso temporale, questa variante mai vista prima è nata in un mondo devoto all'ordine.\"\nBottino:\nFenditure del Tempo\nMercante:\nSorotis\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000"}
MultiLanguageItemData['it'][206676] = {name = "[q4]Drago della Viltempesta", additional_info = "[q7]Si vincola alla Brigata\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"La Legione Infuocata ha sconfitto i draghi in un lontano flusso temporale. Questi vildragoni hanno preferito la corruzione e la schiavitù alla distruzione.\"\nBottino:\nFenditure del Tempo\nMercante:\nFalara Cantanotte\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000"}
MultiLanguageItemData['it'][206678] = {name = "[q4]Guinzaglio del Segugio Sulfureo", additional_info = "[q7]Si vincola alla Brigata\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda un Segugio Sulfureo cavalcabile.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"L'Impero Nero ha soggiogato questi segugi umiliati e denigrati. Assolutamente obbedienti, servono con ancora più forza.\"\nBottino:\nFenditure del Tempo\nMercante:\nApprovvigionatrice Qorra\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000"}
MultiLanguageItemData['it'][206679] = {name = "[q4]Mastodonte Perfetto", additional_info = "[q7]Si vincola alla Brigata\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare un Mastodonte Perfetto, una cavalcatura terrestre.\n[q2]Evoca e congeda un Mastodonte Perfezionato.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"La perfezione, come la bellezza, è nell'occhio di chi guarda. Ma la vista può essere chirurgicamente potenziata.\"\nBottino:\nFenditure del Tempo\nMercante:\nVella la Trivella\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000"}
MultiLanguageItemData['it'][206680] = {name = "[q4]Redini del Dominatore della Genia del Flagello", additional_info = "[q7]Si vincola alla Brigata\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura volante.\n[q2]Evoca e congeda un Dominatore della Progenie del Gelo della Genia del Flagello, una cavalcatura volante.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un tempo vincolati al Flagello, questi draghi non morti esistono solo per diffondere morte, malattia e distruzione.\"\nBottino:\nFenditure del Tempo\nMercante:\nBarone Sliver\nZona:\nBacino del Forte di Tyr\nCosto:\n3.000"}
