MultiLanguageItemData['it'][208235] = {name = "Occhiali da Sole di Scorta di Pedgi", additional_info = "Oggetto di missione\n[q2]Usa: Permette di indossare gli occhiali da sole speciali di Pedgi e ammirare il ritmo del mondo! Gli occhiali sono stati potenziati per segnalare gli oggetti la cui firma temporale non corrisponde a quella della nostra linea temporale.\n[q]\"Gli occhiali da sole di Pedgi. Potenziato da Melly per vedere il ritmo dei flussi temporali.\""}
MultiLanguageItemData['it'][208236] = {name = "Metronografo di Melly", additional_info = "Oggetto di missione\nUnico\n[q2]Usa: Esilia le vicine entità fuori dal tempo nella loro linea temporale.\n[q]\"L'attrezzo di misurazione del ritmo di Melly brevettato. Potenziato per identificare e correggere le anomalie temporali.\""}
