MultiLanguageItemData['it'][208938] = {name = "Particolato Metamorfico", additional_info = "Oggetto di missione\n[q]\"Le braci persistenti in questa cenere sembrano cambiare forma mentre le guardi.\""}
MultiLanguageItemData['it'][208939] = {name = "[q4]Gorridar, Lamanera del Fenditore", additional_info = "Cosmetico\n[q7]Si vincola alla Brigata\n{Una mano} {Spada}\n{1 Danni} {Velocità 2.60}\n(0.4 danni per secondo)\nQuesto oggetto non è disponibile per la vendita diretta. Consulta il Diario del Viaggiatore per scoprire come ottenere la Cassa di Armi Cosmiche.\n[q]\"Malizia e odio sono stati infusi in un'arma progettata per devastare interi mondi. Attenzione a chi invidia una tale lama.\"\n[q2]Usa: Aggiungi questo aspetto alla collezione della Brigata.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][208940] = {name = "[q4]Cantavuoto, Bastone dell'Aralda", additional_info = "Cosmetico\n[q7]Si vincola alla Brigata\n{Due mani} {Bastone}\n{1 - 2 Danni} {Velocità 3.60}\n(0.4 danni per secondo)\nQuesto oggetto non è disponibile per la vendita diretta. Consulta il Diario del Viaggiatore per scoprire come ottenere la Cassa di Armi Cosmiche.\n[q]\"Un dono di Dimensius conferito all'apice dell'Impero Nero. Coloro che sono toccati dall'ombra vengono attratti dai suoi inquietanti sussurri.\"\n[q2]Usa: Aggiungi questo aspetto alla collezione della Brigata.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][208941] = {name = "[q4]M'thorus, Pugnale del Grande Progetto", additional_info = "Cosmetico\n[q7]Si vincola alla Brigata\n{Una mano} {Pugnale}\n{1 Danni} {Velocità 1.80}\n(0.6 danni per secondo)\nQuesto oggetto non è disponibile per la vendita diretta. Consulta il Diario del Viaggiatore per scoprire come ottenere la Cassa di Armi Cosmiche.\n[q]\"Le ombre non possono essere sconfitte. Il disordine dev'essere colpito ogni volta che prende il sopravvento. I veri figli dei Titani ascolteranno la chiamata dei loro creatori.\"\n[q2]Usa: Aggiungi questo aspetto alla collezione della Brigata.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][208942] = {name = "Dispaccio Tre del Preservatore", additional_info = "Segreti di Azeroth\nSi vincola alla raccolta\n[q]\"Una nota che descrive un manufatto a forma di globo che i Preservatori dovrebbero raccogliere.\"\n[q2]<Fare Clic Destro per Leggere>"}
MultiLanguageItemData['it'][208943] = {name = "[q4]Arsenale: Cassa di Armi Cosmiche", additional_info = "[q7]Si vincola alla Brigata\n[q2]Usa: Ottieni gli aspetti contenuti nella Cassa di Armi Cosmiche.\n[q]\"Armamenti forgiati dalla trama primordiale del cosmo. Chi abbia raccolto questa collezione e perché l'abbia fatto rimane un mistero. Impugnare questi pezzi attirerà l'attenzione di coloro che bramano questo potere.\""}
MultiLanguageItemData['it'][208944] = {name = "Globo di Rathmus", additional_info = "Segreti di Azeroth\nSi vincola alla raccolta\nQuesto oggetto avvia una missione\n[q]\"Scritte titaniche adornano le fasce metalliche che circondano il globo luminoso.\""}
MultiLanguageItemData['it'][208945] = {name = "[q7]Cassa Imprevedibile", additional_info = "[q7]Si vincola alla Brigata\n[q2]Usa: Da aprire per ottenere 500 Fiocchi Imprevedibili.\n[q]\"Sfortunatamente, per il benessere della sequenza temporale, si consiglia di aprirla dopo l'invio.\""}
MultiLanguageItemData['it'][208946] = {name = "Runa Ardente", additional_info = "Oggetto di missione\n[q]\"Una misteriosa incisione che emana un calore fastidioso.\""}
MultiLanguageItemData['it'][208947] = {name = "Innaffiatoio Incantato", additional_info = "Oggetto di missione\nUnico\n[q2]Usa: Spruzza l'acqua sui cespugli incantati, donando loro l'energia per liberarsi da Magnolia DeQuerc.\n[q]\"Più potente di un innaffiatoio medio.\""}
MultiLanguageItemData['it'][208949] = {name = "Pietra del Ritorno Riscaldata", additional_info = "Oggetto di missione\n[q]\"Calda e invitante, perfetta per riscaldare le mani.\""}
MultiLanguageItemData['it'][208950] = {name = "Fibra di Smeraldo", additional_info = "Oggetto di missione\n[q]\"Una fibra ricca che possiede una forza incredibile.\""}
MultiLanguageItemData['it'][208951] = {name = "[q7]Formazione Imprevedibile", additional_info = "[q7]Si vincola alla Brigata\n[q2]Usa: Da frantumare per ottenere 1000 Fiocchi Imprevedibili.\n[q]\"Una formazione cristallina emersa subito prima della collisione di due flussi temporali che ha compresso le sabbie del tempo.\""}
MultiLanguageItemData['it'][208952] = {name = "[q7]Lettera di Encomio di Soridormi", additional_info = "[q7]Si vincola alla Brigata\n[q2]Usa: Da leggere per ottenere 1000 reputazione con Soridormi.\n[q]\"Una lettera di stima firmata da Soridormi.\""}
