MultiLanguageItemData['it'][209996] = {name = "Runa Spiravincolo", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti affligge con Sifone Spiravincolo, vincolandoti a qualsiasi creatura rara nel Sogno di Smeraldo.\n\n Sconfiggere creature rare mentre l'effetto di Sifone Spiravincolo è attivo fornisce Spiravincolo Teso. (5 S Recupero)\n[q]\"La runa di Lydiara aspira lo Spiravincolo Teso dalle potenti creature del Sogno di Smeraldo.\""}
MultiLanguageItemData['it'][209997] = {name = "[q3]Conoscenza dei Flussi Temporali Distillata", additional_info = "[q7]Si vincola alla Brigata\nUnico (5)\n[q2]Usa: Aumenta l'esperienza guadagnata dall'uccisione dei mostri e dal completamento delle missioni del 5%.\n\n Completare le spedizioni dei Viaggi nel Tempo aumenta l'effetto e ne estende la durata.\n\n Dopo aver aver raggiunto 4 accumuli, si trasforma in Maestria dei Flussi Temporali , aumentando l'effetto al 30%."}
MultiLanguageItemData['it'][209998] = {name = "[q4]Runa Vincolante di Lydiara", additional_info = "Si vincola alla raccolta\n[q]\"Creata insieme a Lydiara Mormorapiuma.\""}
MultiLanguageItemData['it'][209999] = {name = "Runa del Vincolo d'Ombra di Lydiara", additional_info = "Si vincola alla raccolta\n[q2]Usa: Legarsi a Torciradice, Igira o Volcoross attiva l'Ombrovincolo.\n\n Durante Ombrovincolo, si è affetti da Ombrofuoco Ruggente, che riduce la velocità di movimento del 0-50% in base alla distanza dal bersaglio e ha una probabilità di ridurre la mobilità ogni 5 s. (5 S Recupero)\n[q]\"Una Runa del Vincolo d'Ombra pronta per la sintonizzazione con Fyr'alath.\""}
MultiLanguageItemData['it'][210001] = {name = "[q4]Prototipo di Vello dell'Ordine", additional_info = "Si vincola alla raccolta\n[q]\"Un vello prototipo creato da Shalasar usando Macchie di Cenere Radiosa.\""}
MultiLanguageItemData['it'][210002] = {name = "Verga da Rabdomante Cinerea", additional_info = "Oggetto di missione\n[q2]Usa: Estrae la Macchia di Cenere Radiosa da armi o armature potenti (EPICHE). L'oggetto utilizzato verrà DISTRUTTO e non sarà più recuperabile. (5 Min Recupero)\n[q]\"Una verga da rabdomante che permette di disincantare potenti pezzi d'equipaggiamento per cercare le Macchie di Cenere Radiosa.\""}
MultiLanguageItemData['it'][210003] = {name = "[q4]Vello Sofico di Shalasar", additional_info = "Si vincola alla raccolta\n[q]\"Creato insieme a Shalasar Lucecalante.\""}
MultiLanguageItemData['it'][210005] = {name = "[q3]10.2 Monster - Weapon - Staff - 10.1.5 Weapon Staff - Staff_2H_Druid_C_02_Color1", additional_info = "Si vincola all'equipaggiamento\n{Due mani} {Bastone}\n{7 - 10 Danni} {Velocità 3.60}\n(2.4 danni per secondo)\n+28 Intelletto\n+9 Tempra\n[q2]+ 8 Critico\n[q2]+ 5 Celerità\nPrezzo di vendita:"}
MultiLanguageItemData['it'][210008] = {name = "[q4]Runa del Vincolo Infuocato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il fuoco purificherà gli ostacoli sulla tua strada!\"\nPromozione:\nCataclysm Classic"}
MultiLanguageItemData['it'][210009] = {name = "[q4]Prototipo di Impugnatura di Erbonirica", additional_info = "Si vincola alla raccolta\n[q]\"Una runa prototipo creata da Erden partendo dall'Erbonirica Adombrata coriace.\""}
MultiLanguageItemData['it'][210010] = {name = "Appunti di Erden sulle Spore Simbiotiche", additional_info = "Si vincola alla raccolta\n[q2]Usa: Condivide gli appunti di Erden con un conciatore e gli insegna temporaneamente come creare l'Impugnatura di Erbonirica di Erden. Il conciatore deve essere nello stesso gruppo. (30 Min Recupero)\n[q]\"Appunti dettagliati sulle cose necessarie per creare un'Impugnatura di Spore Luminose Simbiotiche sperimentale. Scritti dal Maestro Conciatore Erden.\""}
MultiLanguageItemData['it'][210011] = {name = "Appunti di Shalasar sulla Magia Sofica", additional_info = "Si vincola alla raccolta\n[q2]Usa: Condivide gli appunti di Shalasar con un incantatore e gli insegna temporaneamente come creare il Vello Sofico di Shalasar. L'incantatore deve essere nello stesso gruppo. (30 Min Recupero)\n[q]\"Appunti dettagliati sulle cose necessarie per creare un Vello Sofico sperimentale. Scritti dalla Maestra Incantatrice Shalasar Lucecalante.\""}
MultiLanguageItemData['it'][210012] = {name = "Impugnatura di Spore Luminose Simbiotiche di Erden", additional_info = "Si vincola alla raccolta\n[q2]Usa: Tenta di vincolare l'Impugnatura di Spore Luminose Simbiotiche a Fyr'alath, infliggendo danni da ombrofuoco pari al 10-25% della salute massima ogni secondo per 10 sec. (30 S Recupero)\n[q]\"Un'Impugnatura di Spore Luminose mai testata.\""}
MultiLanguageItemData['it'][210014] = {name = "[q3]Semi Senza Età Misteriosi", additional_info = "Oggetto di missione\nUnico (20)\n[q2]Usa: Pianta un seme delle dimensioni appropriate presso un appezzamento di Suolo del Semonirico.\n[q]\"Semonirici in attesa di essere risvegliati.\""}
MultiLanguageItemData['it'][210016] = {name = "Manto di Sognagufo", additional_info = "Oggetto di missione\nUnico\n[q2]Usa: Entra in uno stato di furtività. Entrare in combattimento o lanciare abilità interrompe l'effetto. Se si è troppo vicini ai nemici, si può essere individuarti. (8 S Recupero)\n[q]\"Richiama il sognagufo Bodwin per fornirti un'aura di furtività temporanea.\""}
MultiLanguageItemData['it'][210017] = {name = "Pesce Fungino", additional_info = "Follia Fungina\n[q]\"Alcuni dicono che sia un pesce, ma in realtà sembra solo un fungo mezzo mangiato.\""}
