MultiLanguageItemData['it'][210057] = {name = "[q4]Redini della Fieronirica della Fioritura Mattutina", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 18 con i Custodi del Sogno.\nPrezzo di vendita:\n[q]\"Conosciute per l'abbondante energia che emanano, queste fiere sono notoriamente dispettose. Il loro ruggito disperde i primi uccelli del mattino che le risvegliano.\"\nMercante:\nTalisa Fiorlieve\nZona:\nSogno di Smeraldo\nCosto:\n1"}
MultiLanguageItemData['it'][210058] = {name = "[q4]Redini della Fieronirica del Sole Serale", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 18 con i Custodi del Sogno.\nPrezzo di vendita:\n[q]\"Queste fieroniriche sono feroci in battaglia, ma spesso se ne stanno sdraiate, pigre e indolenti, nei campi aperti. Dopo aver assorbito la calda luce del giorno, la loro fiamma risplende ancor più luminosa.\"\nMercante:\nTalisa Fiorlieve\nZona:\nSogno di Smeraldo\nCosto:\n1"}
MultiLanguageItemData['it'][210059] = {name = "[q4]Redini della Fieronirica della Notte Invernale", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Queste fieroniriche notturne portano con sé il gelo dell'inverno e spesso vanno in letargo per giorni, se nessuno le sveglia.\"\nBottino:\nCassa del Semonirico\nZona:\nSogno di Smeraldo"}
MultiLanguageItemData['it'][210060] = {name = "[q4]Redini della Fieronirica del Vespro d'Ombra", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Una fieronirica colpisce rapidamente dalle ombre, catturando piccoli animali e scivolando nell'oscurità senza emettere un suono. I pochi fortunati che hanno visto una fieronirica nutrirsi sanno quanto si divertono con la loro preda, prima di iniziare il pasto.\"\nImpresa:\nGloria dell'incursore del Sogno\nCategoria:\nSpedizioni e incursioni"}
