MultiLanguageItemData['it'][210184] = {name = "[q4]Pozione Mezza Piena del Sonno Senza Sogni", additional_info = "Si vincola alla raccolta\nUsa: Da studiare per aumentare la Conoscenza dell'Alchimia delle Isole dei Draghi di 3.\nRichiede Alchimia delle Isole dei Draghi (25)\n[q]\"Da queste parti sarebbe stato più semplice chiamarla \"acqua\".\""}
MultiLanguageItemData['it'][210185] = {name = "[q4]Pozione a Spruzzo della Narcolessia", additional_info = "Si vincola alla raccolta\nUsa: Da studiare per aumentare la Conoscenza dell'Alchimia delle Isole dei Draghi di 3.\nRichiede Alchimia delle Isole dei Draghi (25)\n[q]\"Visto che il suo obiettivo sarebbe quello di far addormentare un nemico, sembra quasi un controsenso inzupparlo nel processo.\""}
MultiLanguageItemData['it'][210189] = {name = "Lenti Truccate dell'Esarca Hataaru", additional_info = "Oggetto di missione\n[q]\"Una piccola lente d'oro, consumata dal tempo e dall'uso. Le sfaccettature intagliate con precisione consentono agli artigiani di vedere i canali energetici che attraversano i cristalli.\""}
MultiLanguageItemData['it'][210190] = {name = "[q4]Radice Ardente", additional_info = "Si vincola alla raccolta\nUsa: Da studiare per aumentare la Conoscenza dell'Alchimia delle Isole dei Draghi di 3.\nRichiede Alchimia delle Isole dei Draghi (25)\n[q]\"Brucia al tocco. Sarebbe un fantastico catalizzatore per le tue misture, ma buona fortuna a convincere un qualsiasi erbalista a giocare con il fuoco.\""}
MultiLanguageItemData['it'][210193] = {name = "[q4]Acchiappasogni Sperimentale", additional_info = "Si vincola alla raccolta\nUsa: Da studiare per aumentare la Conoscenza dell'Ingegneria delle Isole dei Draghi di 3.\nRichiede Ingegneria delle Isole dei Draghi (25)\n[q]\"Portare un magnete nel Sogno di Smeraldo non lo rende automaticamente un acchiappasogni, ma valeva la pena provarci.\""}
MultiLanguageItemData['it'][210194] = {name = "[q4]Insonniatron", additional_info = "Si vincola alla raccolta\nUsa: Da studiare per aumentare la Conoscenza dell'Ingegneria delle Isole dei Draghi di 3.\nRichiede Ingegneria delle Isole dei Draghi (25)\n[q]\"Un dispositivo calibrato con attenzione che emette un suono acuto udibile solo dai Druidi addormentati.\""}
MultiLanguageItemData['it'][210197] = {name = "[q4]Batteria Non Schiusa", additional_info = "Si vincola alla raccolta\nDurata: 3 giorni\nUsa: Da studiare per aumentare la Conoscenza dell'Ingegneria delle Isole dei Draghi di 3.\nRichiede Ingegneria delle Isole dei Draghi (25)\n[q]\"Anche se viene solitamente confusa con un uovo smarrito, ci si potrebbe chiedere cosa sarebbe potuto nascere se l'incubazione non fosse stata interrotta.\""}
