MultiLanguageItemData['it'][210831] = {name = "[q4]Diluvion", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nDevi avere una cavalcatura Lontruk nella tua collezione poter infonderne un'altra con l'energia dei sogni.\n\n\n[q]\"Immagina un sogno così coinvolgente da sembrare vero. Qualcuno potrebbe persino chiamarlo un delirio.\"\nMercante:\nElianna\nZona:\nSogno di Smeraldo\nCosto:\n1"}
MultiLanguageItemData['it'][210833] = {name = "[q4]Artigliont", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nDevi avere una cavalcatura Sognartiglio nella tua collezione poter infonderne un'altra con l'energia dei sogni.\n\n\n[q]\"Alcuni sogni a occhi aperti sono pieni di possibilità meravigliose, ma vanno in pezzi quando si scontrano con le limitazioni della realtà. Alcuni sogni non sono così appesantiti, nemmeno quando trasportano un cavaliere.\"\nMercante:\nElianna\nZona:\nSogno di Smeraldo\nCosto:\n1"}
