MultiLanguageItemData['it'][210964] = {name = "[q3]Piccolo Irathion", additional_info = "Si vincola alla raccolta\n[q2]Usa: Ti insegna a evocare e congedare questa mascotte.\n[q2]Clicca col pulsante destro per evocare e congedare questa mascotte.\nRichiede dal livello 1 al 80 ( 80)"}
