MultiLanguageItemData['it'][210969] = {name = "[q4]Salatranza", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nDevi avere una cavalcatura Salamantera nella tua collezione poter infonderne un'altra con l'energia dei sogni.\n\n\n[q]\"Benché l'attenzione della maggior parte delle salamantere salti da un'attrazione all'altra, questa si gode lunghi periodi di profonda osservazione.\"\nMercante:\nElianna\nZona:\nSogno di Smeraldo\nCosto:\n1"}
MultiLanguageItemData['it'][210970] = {name = "Pegno Sbriciolato", additional_info = "Follia Fungina\n[q]\"Un vecchio pegno che apparteneva a un Terrigeno.\""}
MultiLanguageItemData['it'][210973] = {name = "[q4]Manta del Mana Centracuori", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura volante.\nEvoca e congeda una Manta del Mana Centracuori, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Qualcuno una volta ha detto a questa manta del mana che era adorabile. Da allora, lei insegue quella sensazione positiva.\"\nEvento mondiale:\nAmore nell'Aria\nCosto:\n270"}
MultiLanguageItemData['it'][210974] = {name = "[q3]Occhi Solo per Te", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Ignora tutti coloro che non sono membri del gruppo. (30 Min Recupero)"}
MultiLanguageItemData['it'][210975] = {name = "[q3]Simulatore Modulato di Appuntamenti", additional_info = "Si vincola all'uso\nGiocattolo\n[q2]Usa: Posiziona un Simulatore Modulato di Appuntamenti per massimo 2 hrs che ti permette di vedere il mondo da una prospettiva diversa.\n\n Un dispositivo di occultamento collegato alla macchina assicura che solo i membri del gruppo o dell'incursione possano vedere la macchina e i suoi effetti.\n\n Utilizzabile solo all'esterno. (2 Ore Recupero)\nPrezzo di vendita:"}
