MultiLanguageItemData['it'][212227] = {name = "[q4]Redini della Volpe Pelosona", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda la cavalcatura Volpe Pelosona.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Queste creature magiche si nutrono di amore e amicizia.\"\nEmporio"}
MultiLanguageItemData['it'][212228] = {name = "[q4]Redini della Volpe Celeste Volteggiante", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda la cavalcatura Volpe Celeste Volteggiante.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Per salire in cielo sulla più leale e adorabile volpe di Azeroth.\"\nNegozio di gioco"}
MultiLanguageItemData['it'][212229] = {name = "[q4]Redini del Predatore Celeste del Crepuscolo", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda la cavalcatura Predatore Celeste del Crepuscolo.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Soprannominato da alcuni \"l'imbroglione di mezzanotte\", molte coppie lo additano come il motivo per cui le loro strade si sono incrociate di notte.\""}
MultiLanguageItemData['it'][212289] = {name = "Tonico Malvagio degli Spiriti Classici", additional_info = "[q2]Usa: Bere permette di aumentare la rigenerazione di mana del 8% quando non si lancia alcun incantesimo benefico che consumi mana per 5 sec.\n\n Punti Onore ottenuti aumentati del 15%.\n\nDura 1 hour e persiste oltre la morte. Consumare un secondo tonico identico aggiunge 1 hour.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][212292] = {name = "Tonico Malvagio dell'Onore", additional_info = "[q2]Usa: Bere permette di aumentare i Punti Onore ottenuti del 15%. Può essere usato in tutti i contesti PvP classificati e non classificati.\n\nDura 1 hour e persiste oltre la morte. Consumare un secondo tonico identico aggiunge 1 hour.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][212295] = {name = "Tonico Malvagio della Furia Manifesta", additional_info = "[q2]Usa: Alla morte, la rabbia si manifesta con un elementale furioso che si vendica sui nemici per 10 sec. Può attivarsi solo una volta ogni 2 min.\n\n Punti Onore ottenuti aumentati del 15%.\n\nDura 1 hour e persiste oltre la morte. Consumare un secondo tonico identico aggiunge 1 hour.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][212298] = {name = "Tonico Malvagio della Demolizione", additional_info = "[q2]Usa: I colpi di grazia contro i giocatori aumentano i danni inflitti del 8% e i danni subiti del 4% per 20 sec. Si accumula fino a 5 volte. Se si viene uccisi con questo effetto attivo, l'attaccante prende una parte di questo potere.\n\n Punti Onore ottenuti aumentati del 15%.\n\nDura 1 hour e persiste oltre la morte. Consumare un secondo tonico identico aggiunge 1 hour.\nPrezzo di vendita:"}
