MultiLanguageItemData['it'][212361] = {name = "[q2]Opportunista", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Aumenta la probabilità di critico del 50% per 4 sec dopo aver inflitto danni a un nemico stordito.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][212362] = {name = "[q2]Infiorescenza di Solealto", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: I colpi critici eruttano in un'esplosione infuocata, infliggendo danni da fuoco ai nemici entro 15 m dal bersaglio.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][212365] = {name = "[q2]Zelo", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Quando si ha più del 80 % della salute massima, gli attacchi consumano salute per infliggere danni da sacro pari all'ammontare consumato. (1 s di tempo di recupero)\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][212366] = {name = "[q2]Vantaggio dell'Arcanista", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Gli attacchi consumano una parte dello scudo di assorbimento per infligge danni da arcano pari all'ammontare consumato. (10 s di tempo di recupero)\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][212367] = {name = "[q3]Involucro di Emblemi Risvegliati del Dragone", additional_info = "Si vincola alla raccolta\n[q2]Usa: Recupera 15 Emblemi Risvegliati del Dragone. Questi emblemi ignorano il limite massimo stagionale.\nCompleta la missione \"Sognare emblemi\" da Vaskarn all'Accampamento Centrale per poter depotenziare i tuoi Emblemi Onirici.\nDevi completare la missione \"Emblemi risvegliati, possibilità illimitate\" da Vaskarn a Valdrakken per poter depotenziare i tuoi Emblemi Risvegliati."}
