MultiLanguageItemData['it'][213026] = {name = "[q0]Spazzola dei Draconidi Massiccia", additional_info = "[q]\"I dragoidi di grandi dimensioni maneggiano spazzole come questa con sorprendente destrezza per dipingere case o intricati disegni murali.\"\nPrezzo di vendita:"}
