MultiLanguageItemData['it'][213029] = {name = "[q0]Forchettone dei Draconidi Piegato", additional_info = "[q]\"Un forcone dei draconidi potrà sembrare banale a un occhio inesperto, ma questo attrezzo dimostra la raffinatezza di chi l'ha prodotto.\"\nPrezzo di vendita:"}
