MultiLanguageItemData['it'][213595] = {name = "[q4]Filo del Solcavento Piumato", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Controllare la velocità attuale e l'elevazione prima della salita a bordo. Evitare alberi e altri oggetti alti. Non è concesso di restituire o chiedere il rimborso degli aquiloni danneggiati.\" - Manuale di Istruzioni del Vento\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213596] = {name = "[q4]Redini del Destriero del Vento della Tempesta Diurna", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Si dice che quando il fulmine colpirà il sole, una bestia scintillante in armatura rossa discenderà dal cielo. Il Destriero del Vento della Tempesta Diurna non ha mai sentito parlare di queste leggende ed è stato qui tutto il tempo.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213597] = {name = "[q4]Redini del Destriero del Vento Boschivo", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il manto di questo Destriero del Vento non si limita a essere colorato per abbinarsi alla sua terra natia, ma di solito contiene anche pezzi di corteccia e foglie.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213598] = {name = "[q4]Redini del Destriero del Vento Scattante", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"I Destrieri del Vento sono incredibilmente gentili e facili da addestrare... se riesci a catturarne uno.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213600] = {name = "[q4]Redini del Quilen Marmoreo", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Creato da un Occultista Mogu che ha dato vita alla sua pietra preferita.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213601] = {name = "[q4]Redini del Guardiano Quilen", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Quando Quan l'Implacabile cadde in battaglia, i suoi fedeli segugi aspettarono il suo ritorno. Millenni dopo, attendono pazienti.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213602] = {name = "[q4]Redini della Gru Cavalcabile Aurea", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Si dice che un imperatore una volta pagò una grossa somma per una gru dorata. Dopo aver scoperto che la gru fosse solo tinta del prezioso metallo, si nascose nelle sue stanze per una settimana in preda alla vergogna.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213603] = {name = "[q4]Redini della Gru Cavalcabile Chiara", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Ed ecco, mi apparve... una gru pallida?\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213604] = {name = "[q4]Redini della Gru Cavalcabile Tropicale", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questo nativo della Foresta di Giada usa la sua colorazione per mimetizzarsi.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213605] = {name = "[q4]Redini della Gru Cavalcabile Rosa", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questo uccello colorato è spesso confuso con un fenicottero o un marabù.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213606] = {name = "[q4]Redini della Gru Cavalcabile Argentea", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questo alto uccello è tra le più aggraziate ed eleganti delle gru, leggermente più della Gru di Bronzo ma leggermente meno della Gru Dorata.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213607] = {name = "[q4]Redini della Gru Cavalcabile Lussuosa", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Un uccello maestoso, ma un po' schizzinoso.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213608] = {name = "[q4]Redini del Caprone Cavalcabile Nevoso", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Le capre delle nevi del Massiccio del Kun-Lai sono note per scalare persino le vette più alte alla ricerca di semi di kafa e depositi di sale.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213609] = {name = "[q4]Redini del Mini Caprone Cavalcabile Rosso", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questa capra compensa la modesta dimensione con la testardaggine.\"\nEvento mondiale:\nMists of Pandaria: Remix"}
