MultiLanguageItemData['it'][213621] = {name = "[q4]Redini dello Pterrordattilo di Giada", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questa cavalcatura preferita dagli Zandalari ha una voce meravigliosa, o almeno così crede.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213622] = {name = "[q4]Redini dello Pterrordattilo Notturno", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli studiosi interpretano il terribile stridio di questa creatura come: \"Temetemi, io sono la notte!\"\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213623] = {name = "[q4]Redini dell'Urlacieli Insanguinato", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questo dinosauro cova ancora il rancore dei suoi antenati dall'invasione degli Zandalari.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213624] = {name = "[q4]Mastodonte di Cobalto", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Ciò che iniziò come una macchina cavalcabile d'estrazione e di registrazione divenne rapidamente portatrice di caos quando gli ingegneri si chiesero se avrebbero potuto renderla ancora più interessante.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213625] = {name = "[q4]Mastodonte di Vilferro", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questa macchina da guerra è stata rubata da una linea temporale in cui Garrosh Malogrido si è unito alla Legione Infuocata. Diciamo che non è rimasto molto di quella linea temporale.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213626] = {name = "[q4]Redini della Tigre Cavalcabile Viola degli Shandaren", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Se devi svegliare una tigre, usa un lungo bastone. O ancor meglio, chiedi a un tuo amico di svegliarla al posto tuo.\" - Proverbio dei Pandaren\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213627] = {name = "[q4]Redini del Mushan Mantopallido", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il Mushan Mantopallido è il più gustoso tra i Mushan, ma detesta che glielo si ricordi.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][213628] = {name = "[q4]Redini del Mushan Calcafiume", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Il Mushan è una bestia vorace. Anche se può essere addomesticata, richiederà una seconda, terza e persino quarta colazione ogni giorno.\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
