MultiLanguageItemData['it'][215169] = {name = "[q2]Lanterna Inestinguibile", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+64 [Agilità o Intelletto]\n[q2]Equipaggia: Gli incantesimi e le abilità d'attacco a distanza hanno un'alta probabilità di risvegliare la fiamma della lanterna, fornendo un accumulo di Luce di Lampada fino a un massimo di 15 volte.\n\n Dopo 30 sec di raccolta di accumuli, la Luce di Lampada si consuma, attirando una quantità equivalente di lucciole che caricano il successivo bersaglio attaccato, esplodendo e infliggendo ( 1 * 151 ) danni da fuoco per lucciola.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][215170] = {name = "[q2]Trappola Abissale", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+64 [Agilità o Forza]\n[q2]Usa: Piazza una trappola abissale ai tuoi piedi. Quando un nemico si avvicina a meno di 3 m, si crea una bolla d'acqua gigante per 10 sec. Tutti i nemici all'interno della bolla subiscono ( 1 * 195 ) danni da gelo ogni secondo.\n\n La trappola persiste per 1 min prima di venire automaticamente disarmata. (1 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][215171] = {name = "[q2]Flauto dell'Amico Fungino", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+64 Intelletto\n[q2]Equipaggia: Gli incantesimi e le abilità hanno una probabilità di dissotterrare un Amico Fungino colorato che cura gli alleati di 4513 , ti rigenera 439 mana o infligge [ 1028 * (3)] danni da natura in 3 sec a un nemico vicino. (1s di recupero)\n[q]\"Gli Amici Fungini non muoiono mai davvero. Invece, le loro spore si instillano nel terreno, per poi far nascere di nuovo un Amico Fungino.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][215172] = {name = "[q2]Nodo Inanellato di Seta", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+64 [Agilità o Forza]\n[q2]Usa: Srotola una miriade di ragnatele che intrappolano i nemici frontali, riducendone i danni a te inflitti del 30 %, fino a un massimo di 5255 danni totali, e la velocità d'attacco del 15 % per 15 sec.\n\n [La riduzione della velocità d'attacco è meno efficace contro i nemici di livello superiore a 80 .] (1 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][215173] = {name = "[q3]Siero dei Sensi Illimitati", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]+ 48 Schivata\n[q2]+ 48 Parata\n[q2]Equipaggia: Consumare sistematicamente una piccola dose del siero quando si entra in combattimento migliora i sensi fino al limite.\n In questo stato, la probabilità di schivata e parata ha una probabilità di permetterti di rispondere all'attacco, infliggendo Y danni fisici all'attaccante.\n[q]\"Gli effetti collaterali includono perdita di equilibrio, vomito, dolore estremo, perdita di memoria a breve termine, perdita di memoria a lungo termine, perdita di funzionalità motorie, allucinazioni e un insaziabile appetito per piccoli insetti.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][215174] = {name = "[q2]Mistura: Bacio della Morte", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+64 [Agilità o Forza o Intelletto]\n[q2]Usa: Bere dalla fiala rilascia le tossine nelle vene, aumentando tutte le statistiche secondarie di 106 per 30 sec.\n\n Saltare somministra l'antidoto, ponendo fine all'effetto.\n\n Se l'antidoto non viene somministrato prima della fine dell'effetto, si resta storditi per 5 sec. (2 Min, 30 S Recupero)\n[q]\"ATTENZIONE: La mancata somministrazione dell'antidoto poco dopo il consumo potrebbe portare alla morte.\"\nPrezzo di vendita:"}
