MultiLanguageItemData['it'][216624] = {name = "[q2]Marchio dell'Arroganza", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Gli attaccanti vengono affetti da Marchio dell'Arroganza, che infligge danni da ombra ogni 2 s per 10 sec e si accumula fino a 5 volte.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][216625] = {name = "[q2]Assalto Lampo", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Le abilità in mischia hanno una probabilità del 100% di attivare 4-7 attacchi automatici aggiuntivi. (10 s di tempo di recupero)\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][216626] = {name = "[q2]Assassinio", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Quando si attacca un nemico con meno del 10% della salute massima, si tenta di lanciare Assassinio, infliggendo danni da ombra pari al 100% della propria salute massima.\n\n È possibile tentare di lanciare Assassinio su un nemico solo una volta.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][216627] = {name = "[q2]Scudo del Mastro Meccanista", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Fornisce uno scudo che assorbe danni pari al 15% della salute massima.\n\n Lo scudo si rigenera dopo non aver subito danni per 5 sec.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][216628] = {name = "[q2]Fuoco della Vittoria", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Uccidere un nemico fa eruttare fiamme, infliggendo danni da fuoco ai nemici e rigenerando salute agli alleati entro 12 m.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][216629] = {name = "[q3]Traslazione", additional_info = "Gemma Ingranaggio\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Apprendi il seguente incantesimo.\n\n Traslazione\nTi teletrasporta in avanti di 20 m o finché non si incontra un ostacolo, rimuovendo tutti gli effetti di stordimento e immobilizzazione.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Ingranaggio.\""}
MultiLanguageItemData['it'][216630] = {name = "[q3]Balzo Eroico", additional_info = "Gemma Ingranaggio\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Apprendi il seguente incantesimo.\n\n Balzo Eroico\nPermette di balzare verso la posizione bersaglio, impattando con forza distruttiva e infliggendo (23.5% of Spell power + 23.5% of Attack power) danni fisici a tutti i nemici entro 8 m.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Ingranaggio.\""}
MultiLanguageItemData['it'][216631] = {name = "[q3]Capriola", additional_info = "Gemma Ingranaggio\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Apprendi il seguente incantesimo.\n\n Capriola\nUna capriola che ti fa coprire una piccola distanza.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Ingranaggio.\""}
