MultiLanguageItemData['it'][216647] = {name = "[q2]Tempesta di Grandine", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Ogni 3 s si accumula una carica di Tempesta di Grandine. Al raggiungimento di 10 accumuli, la grandine si scatena sui nemici entro 50 m. Ogni impatto infligge danni da gelo e applica Freddo Stordente.\n\n Freddo Stordente\nRiduce la velocità di movimento del 30% e riduce i danni inflitti del 10%. Attaccare rimuove un accumulo di Freddo Stordente.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][216648] = {name = "[q2]Fronte Gelido", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Le abilità hanno una probabilità di fornire a massimo 5 alleati uno scudo che assorbe i danni subiti, equamente suddivisi, e che affligge con Freddo Stordente tutti i nemici entro 50 m.\n\nFreddo Stordente\nRiduce la velocità di movimento del 30% e riduce i danni inflitti del 10%. Attaccare rimuove un accumulo di Freddo Stordente.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
