MultiLanguageItemData['it'][216882] = {name = "Voce del Registro: 467-21-5", additional_info = "Oggetto di missione\n[q]\"Osservazioni: si nota un'allarmante espansione di Micelio che si insinua nella vegetazione locale. I Fungariani mostrano una risposta amplificata agli stimoli ambientali, presentando un possibile cambiamento del loro comportamento ecologico.\"\n[q2]<Fare Clic Destro per Leggere>"}
MultiLanguageItemData['it'][216888] = {name = "Voce del Registro: 652-12-3", additional_info = "Oggetto di missione\n[q]\"Nota: i Fungariani mostrano delle interazioni micorizzate aggressive, surclassando le specie di funghi locali. La crescita accelerata suscita preoccupazioni sui potenziali squilibri ecologici nell'area interessata.\"\n[q2]<Fare Clic Destro per Leggere>"}
MultiLanguageItemData['it'][216889] = {name = "Voce del Registro: 893-03-9", additional_info = "Oggetto di missione\n[q]\"Osservazioni: i Fungariani si stanno diffondendo oltre il sito iniziale di studio. Osservate intrusioni miceliali aggressive in degli habitat inaspettati. Urge un'indagine per valutare l'impatto ecologico più ampio di questo nuovo comportamento (...)\"\n[q2]<Fare Clic Destro per Leggere>"}
