MultiLanguageItemData['it'][217605] = {name = "Pergamena Senza Tempo dell'Intelletto", additional_info = "[q2]Usa: Infonde intelligenza nel bersaglio, aumentandone l'Intelletto del 4% per 1 hour.\n\n Se il bersaglio è un membro del gruppo o dell'incursione, tutti i membri del gruppo o dell'incursione ne saranno affetti.\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217606] = {name = "Pergamena Senza Tempo della Fermezza", additional_info = "[q2]Usa: Infonde vitalità nel bersaglio alleato, aumentandone la Tempra del 4% per 1 hour.\n\n Se il bersaglio è un membro del gruppo o dell'incursione, tutti i membri del gruppo o dell'incursione ne saranno affetti.\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217607] = {name = "Pergamena Senza Tempo della Selva", additional_info = "[q2]Usa: Infonde un bersaglio alleato con il potere della selva, aumentandone la versatilità del 2% per 1 hour.\n\n Se il bersaglio è un membro del gruppo o dell'incursione, tutti i membri del gruppo o dell'incursione ne saranno affetti.\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217608] = {name = "Pergamena Senza Tempo dell'Urlo di Battaglia", additional_info = "[q2]Usa: Aumenta la potenza d'attacco di tutti i membri del gruppo o dell'incursione entro 100 m del 4% per 1 hour.\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217610] = {name = "Gemma del Ricordo dei Terrigeni", additional_info = "Oggetto di missione\nUnico\n[q]\"La gemma a taglio quadrato è pesante per le dimensioni che ha ed emette un debole bagliore. Progettata per la programmazione e per i ricordi dei Terrigeni, la si può rimuovere e caricare nell'Archivio dei Terrigeni.\""}
MultiLanguageItemData['it'][217612] = {name = "[q4]Collare della Bestia d'Ombra di Zovaal", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Sono stata brava?\" chiese l'anima a Zovaal. \"No. Mi hanno detto che eri tremenda.\"\nImpresa:\nDi ritorno dall'aldilà\nCategoria:\nContenuti specifici"}
