MultiLanguageItemData['it'][217898] = {name = "Preghiera dell'Odio Purificato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Il successivo attacco subito che riduce la salute al di sotto del 35% della salute massima attiva Odio Purificato .\n\nOdio Purificato :\nRigenera completamente la salute, il Vigore e le risorse di classe.\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217899] = {name = "Preghiera dell'Orgoglio Purificato", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Quando non si è in combattimento, si ottiene Orgoglio Purificato .\n\nOrgoglio Purificato :\nPermette di scomparire, entrando in modalità furtiva. L'attacco successivo è sempre un colpo critico.\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217900] = {name = "Preghiera della Rabbia Purificata", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Quando si viene colpiti, si rilascia Rabbia Purificata .\n\nRabbia Purificata :\nInfligge 150000 danni fisici ai nemici entro 8 m e li stordisce per 3 sec.\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217901] = {name = "Tamburi Eterni", additional_info = "[q2]Usa: Aumenta la celerità del 15% per tutti i membri del gruppo o dell'incursione. Dura 40 sec.\n\n Gli alleati che ricevono questo effetto diventano sfiniti e non possono beneficiare di altri effetti simili per 10 min. (2 Min Recupero)\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217902] = {name = "Fiala del Corridore Temporale", additional_info = "[q2]Usa: Aumenta la rigenerazione del mana del 1000% per 6 sec.\n\n Riduce la velocità di movimento del 50%. (6 S Recupero)\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217903] = {name = "[q2]Rivendicazione", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Il 10% dei danni inflitti viene accumulato come Rivendicazione. Ogni 3 sec, l'effetto di Rivendicazione si consuma per curare fino a 3 alleati entro 50 m dell'ammontare consumato.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][217904] = {name = "Fiasca del Potere del Corridore nel Tempo", additional_info = "[q2]Usa: Rigenera 30000 mana e aumenta [<Primary Stat>] del 3 % per 30 min. (5 Min Recupero)\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Scorte aggiuntive possono essere acquistate da Nostwin al Bazar dell'Infinito.\""}
MultiLanguageItemData['it'][217905] = {name = "Fiasca di Salute del Corridore nel Tempo", additional_info = "[q2]Usa: Rigenera 60000 salute e aumenta la Tempra del 3 % per 30 min. (5 Min Recupero)\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Scorte aggiuntive possono essere acquistate da Nostwin al Bazar dell'Infinito.\""}
MultiLanguageItemData['it'][217906] = {name = "Dolcetto per Draco", additional_info = "Unico (3)\n[q2]Usa: Rigenera completamente il Vigore e fornisce un'accelerazione alla velocità di volo. Utilizzabile solo durante il Volo Draconico. (15 S Recupero)\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217907] = {name = "[q2]Calore", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Aumenta le cure ricevute del 10%. Il 75% delle sovracure ricevute viene accumulato come Calore. Ogni 5 sec, l'effetto di Calore viene consumato per curare un alleato ferito entro 50 m dell'ammontare consumato.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][217925] = {name = "Bottiglia di Api", additional_info = "Si vincola alla raccolta\nUnico (3)\n[q2]Usa: Infastidisce ogni nemico entro 40 m dalla destinazione, facendolo entrare in combattimento e affliggendolo con Lividi per 30 sec. Utilizzabile solo all'esterno.\n\n Lividi :\nAumenta i danni subiti da un nemico del 5% per 30 sec. Infliggere danni al nemico ha una probabilità di applicare altri Lividi. (1 Min Recupero)\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Ronzano di rabbia.\""}
MultiLanguageItemData['it'][217926] = {name = "Bottiglia di Api Morte", additional_info = "[q2]Usa: Infligge 1500 danni fisici ai nemici entro 3 m. (1 Min Recupero)\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Ops.\""}
MultiLanguageItemData['it'][217927] = {name = "[q2]Salvezza", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Curare un alleato con meno del 35% della salute massima gli fornisce uno scudo che assorbe danni subiti pari al 50% delle cure fornite.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][217928] = {name = "Pergamena della Resurrezione Senza Tempo", additional_info = "[q2]Usa: Riporta in vita un alleato morto con il 35% della salute e del mana. Non può essere lanciato in combattimento. (30 S Recupero)\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217929] = {name = "Pergamena Senza Tempo della Purificazione", additional_info = "[q2]Usa: Dissolve tutti gli effetti dannosi magici, di maledizione, di malattia e di veleno dal bersaglio alleato. (30 S Recupero)\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Il tempo cura tutte le ferite, le malattie, le maledizioni, le sbornie...\""}
MultiLanguageItemData['it'][217930] = {name = "Buono di Nostwin", additional_info = "[q2]Usa: Riporta a un Bazar dell'Infinito vicino. (15 Min Recupero)\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Grazie per aver fatto acquisti, torna presto!\""}
MultiLanguageItemData['it'][217956] = {name = "Pergamena d'Evocazione Senza Tempo", additional_info = "[q2]Usa: Un rituale che crea un Portale d'Evocazione per 3 min. Il portale può essere usato dagli alleati per evocare il compagno bersaglio. (30 S Recupero)\nRichiede dal livello 10 al 70 ( 70)"}
MultiLanguageItemData['it'][217957] = {name = "[q2]Liberazione", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Il 4% delle cure viene accumulato come Liberazione. Se un alleato ha meno del 50% della salute massima dopo aver ricevuto delle cure da te, gli accumuli di Liberazione vengono consumati per curare fino a 3 alleati entro 50 m dell'ammontare consumato, suddiviso equamente.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
