MultiLanguageItemData['it'][217983] = {name = "[q3]Disimpegno", additional_info = "Gemma Ingranaggio\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Apprendi il seguente incantesimo.\n\n Disimpegno\nBalza indietro, dissolvendo gli effetti di limitazione al movimento e aumentando la velocità di movimento del 25% per 4 sec.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Ingranaggio.\""}
MultiLanguageItemData['it'][217985] = {name = "[q3]Ricordo di Grifone Dorato", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Alliance race]\nUsa: Ti insegna a evocare questa cavalcatura, le cui capacità dipendono da dove ti trovi e dalla tua competenza in Equitazione.\nEvoca e congeda un Ricordo di Grifone Dorato cavalcabile, le cui capacità dipendono da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita: \n[q]\"A Roccavento chiunque adora i leoni... e i grifoni sono per metà leoni. Ecco perché queste creature sono la base del viaggio aereo di tutta l'Alleanza.\"\nMercante:\nTesoriere Amuul\nZona:\nDalaran\nCosto:\n25"}
MultiLanguageItemData['it'][217986] = {name = "[q2]Pezzi di Uova \"Deliziose\"", additional_info = "[q]\"I cuochi Coboldi di Cavafonda concordano che nessun pasto può considerarsi completo senza queste uova.\""}
MultiLanguageItemData['it'][217987] = {name = "[q3]Ricordo di Viverna dei Venti", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[Requires any Horde race]\nUsa: Ti insegna a evocare questa cavalcatura, le cui capacità dipendono da dove ti trovi e dalla tua competenza in Equitazione.\nEvoca e congeda una Viverna dei Venti Verde cavalcabile, le cui capacità dipendono da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita: \n[q]\"Sul dorso di queste onorevoli creature sono state combattute e vinte centinaia di battaglie su una caterva di territori.\"\nMercante:\nTesoriere Amuul\nZona:\nDalaran\nCosto:\n25"}
