MultiLanguageItemData['it'][218105] = {name = "[q3]Benedizione della Lama del Loa", additional_info = "Cosmetico\n[q7]Si vincola alla Brigata\n{Due mani} {Spada}\n{1 - 2 Danni} {Velocità 3.60}\n(0.4 danni per secondo)\nIntegrità 30 / 30\n[q2]Usa: Aggiungi questo aspetto alla collezione della Brigata."}
MultiLanguageItemData['it'][218106] = {name = "Trappola per Rane di Pietraferma", additional_info = "Si vincola alla raccolta\n[q2]Usa: Lancia una Trappola per Rane sul terreno che infligge 20 danni fisici quando un nemico ci cammina sopra e lo stordisce per 6 sec.\n\n Utilizzabile presso lo Stagno di Pietraferma e nelle vicinanze. (10 S Recupero)"}
MultiLanguageItemData['it'][218107] = {name = "Vaso di Scintillucciole", additional_info = "Si vincola alla raccolta\nUnico (20)\n[q2]Usa: Scuotere il vaso fa sì che le scintillucciole all'interno si accendano, fornendo una debole luce.\n\n Con questa luce è possibile localizzare gli oggetti nascosti presso lo Stagno di Pietraferma e nelle zone delle Guardafiamme vicine. (15 S Recupero)\n[q]\"I piccoli insetti luminosi all'interno forniscono una luce colorata.\""}
MultiLanguageItemData['it'][218108] = {name = "[q3]Patto Oscuro", additional_info = "Gemma Ingranaggio\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Apprendi il seguente incantesimo.\n\n Patto Oscuro\nSacrifica il 20% della salute attuale per proteggere da danni subiti pari al 200% della salute sacrificata per 20 sec. Utilizzabile anche sotto effetti di limitazione al controllo del personaggio.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Ingranaggio.\""}
MultiLanguageItemData['it'][218109] = {name = "[q3]Ineluttabilità della Morte", additional_info = "Gemma Ingranaggio\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Apprendi il seguente incantesimo.\n\n Ineluttabilità della Morte\nPer 10 sec, aumenta la velocità di movimento del 35%. La velocità di movimento non può essere ridotta al di sotto del 100% della velocità nomale. Inoltre, rende immuni agli effetti di movimento forzato e alle respinte.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Ingranaggio.\""}
MultiLanguageItemData['it'][218110] = {name = "[q3]Animorfosi", additional_info = "Gemma Ingranaggio\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Apprendi il seguente incantesimo.\n\n Animorfosi\nPermette di trasformarsi in un Volpino per 12 sec, teletrasportandosi di 15 m in avanti e aumentando la velocità di movimento del 50%. È possibile rilanciare Animorfosi ogni pochi secondi per teletrasportarsi di nuovo in avanti.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Ingranaggio.\""}
MultiLanguageItemData['it'][218111] = {name = "[q4]Redini dello Pterrordattilo d'Ambra", additional_info = "Remix: Pandaria\nSi vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli pterrordattili potrebbero mangiarti in pochi secondi e lo farebbero molto volentieri. Credi davvero che sia una buona idea sederti sul suo dorso?\"\nEvento mondiale:\nWoW Remix: Mists of Pandaria"}
MultiLanguageItemData['it'][218112] = {name = "[q3]Sdraio Colorata", additional_info = "Si vincola alla raccolta\nUnico\nGiocattolo\n[q2]Usa: Posiziona una sedia da spiaggia colorata. (5 Min Recupero)\n[q]\"Dopo aver fatto un tuffo per sconfiggere il caldo estivo, riposati sulla stilosa comodità di questa miscela perfetta di calde sfumature del tramonto e rilassanti tonalità arcobaleno.\""}
MultiLanguageItemData['it'][218113] = {name = "Veleno di Pungidolce", additional_info = "Oggetto di missione\nUnico (20)\n[q]\"Piccante e forse dolce, ma comunque da non mangiare.\""}
MultiLanguageItemData['it'][218114] = {name = "[q4]Occhio del Risveglio", additional_info = "Si vincola alla raccolta\n[q2]Usa: Aggiunge un incavo a un oggetto della Stagione 4 di Dragonflight che non ne ha già uno. Può essere usato su pezzi per testa, polsi, fianchi e dita."}
