MultiLanguageItemData['it'][219006] = {name = "[q2]Esca per Grandocchio Ruggente", additional_info = "Usa: Mette sull'amo un'esca per Grandocchio, garantendo di pescarne dalle Pozze di Pesca delle Profondità Risonanti e dei Precipizi Sacri.\n\n L'esca dura 30 min e si accumula fino a 50 volte.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219007] = {name = "[q2]Esca per Creature Elusive", additional_info = "Si vincola alla raccolta\n[q2]Usa: Piazza l'esca, attirando una creatura elusiva dopo un po' di tempo. Chissà cosa potrebbe comparire?\n\n Il tempo di recupero di Esca per Creature Elusive si riduce scuoiando le creature di Khaz Algar.\n\n Utilizzabile solo all'esterno a Khaz Algar.\nRichiede Scuoiatura di Khaz Algar (1)\n[q]\"Un'esca che attira le creature più sfuggenti.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219008] = {name = "[q4]Esca per Bestie Suprema", additional_info = "Si vincola alla raccolta\n[q2]Usa: Piazza l'esca, inducendo una creatura elusiva suprema a uscire dal suo nascondiglio.\n\n Utilizzabile solo nelle Distese Rimbombanti delle Profondità Risonanti.\nRichiede Scuoiatura di Khaz Algar (1)\n[q]\"Un'esca squisita, progettata e creata con lo scopo specifico di attirare allo scoperto una bestia potente.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219009] = {name = "[q3]Esca per Creature Cristallina", additional_info = "Si vincola alla raccolta\n[q2]Usa: Piazza l'esca, attirando una creatura elusiva dopo un po' di tempo. Chissà cosa potrebbe comparire?\n\n Il tempo di recupero di Esca per Creature Elusive si riduce scuoiando le creature di Khaz Algar.\n\n Utilizzabile solo all'esterno a Khaz Algar.\n[q]\"Un'esca allettante che attira allo scoperto le creature più elusive. Infusa di potere cristallino.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219010] = {name = "[q3]Esca per Creature Informe", additional_info = "Si vincola alla raccolta\n[q2]Usa: Piazza l'esca, attirando una creatura elusiva dopo un po' di tempo. Chissà cosa potrebbe comparire?\n\n Il tempo di recupero di Esca per Creature Elusive si riduce scuoiando le creature di Khaz Algar.\n\n Utilizzabile solo all'esterno a Khaz Algar.\n[q]\"Un'esca allettante che attira allo scoperto le creature più elusive. Infusa di un'essenza che trasuda un'energia malvagia.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219011] = {name = "[q3]Esca per Creature Infusa di Spore", additional_info = "Si vincola alla raccolta\n[q2]Usa: Piazza l'esca, attirando una creatura elusiva dopo un po' di tempo. Chissà cosa potrebbe comparire?\n\n Il tempo di recupero di Esca per Creature Elusive si riduce scuoiando le creature di Khaz Algar.\n\n Utilizzabile solo all'esterno a Khaz Algar.\n[q]\"Un'esca allettante che attira allo scoperto le creature più elusive. Infusa di spore magiche.\"\nPrezzo di vendita:"}
