MultiLanguageItemData['it'][219296] = {name = "[q3]Nucleo Entropico degli Skardyn", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]+ 604 Critico\n[q2]Equipaggia: Gli incantesimi hanno una probabilità di destabilizzare l'energia del Vuoto, rilasciandone un frammento corrotto. Recuperare un frammento infonde con il suo potere, aumentando l'Intelletto di 1235 per 15 sec.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219297] = {name = "[q3]Boccale di Idromele Cinereo", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]Equipaggia: Talvolta condivide una bevanda con gli alleati che ti aiutano in combattimento, aumentando il loro attributo primario di 700 per 15 sec e assorbendo 19079 danni subiti. Anche tu ne bevi un sorso, ottenendo 377 [<Primary Stat>] e assorbendo 89032 danni subiti.\n\n Quando si ha meno del 50 % della salute massima, si beve un sorso d'emergenza. L'effetto può verificarsi solo una volta ogni 1 min.\n\nValido solo per le specializzazioni da difensore.\n[q]\"Annacquato così che anche i mortali inferiori possano berlo.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219298] = {name = "[q3]Vespa del Miele Vorace", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 [Agilità o Forza]\n[q2]Usa: Richiama un alleato vorace e cavalca via nel tramonto (o si allontana di $443387rad1 m, a seconda di chi è più vicino), infliggendo ( 1 * 124476 ) danni da fuoco suddivisi tra tutti i nemici lungo la traiettoria. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219299] = {name = "[q3]Materializzatore di Barili Sinergico", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Intelletto\n[q2]Equipaggia: Gli incantesimi hanno una probabilità di caricare il dispositivo e richiamare un Barile di Riempimento vicino alla posizione del bersaglio. Danneggiare il barile lo fa esplodere, infliggendo ( 1 * 84121 ) danni da fuoco suddivisi tra i nemici vicini.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219300] = {name = "[q3]Scheggia di Skarmorak", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Forza\n[q2]Usa: Stringere con forza la scheggia potenzia con l'energia cristallina, aumentando l'indice di maestria di 2756 per 15 sec. (1 Min, 30 S Recupero)\n[q2]Equipaggia: La scheggia risucchia l'energia residua dai nemici sconfitti, aumentando l'indice di maestria di 58 per 15 sec, fino a un massimo di 5 volte.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219301] = {name = "[q3]Lanciatore di Ingranarang Velocizzato", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]Usa: Lancia un ingranarang surriscaldato, infliggendo ( 1 * 41390 ) danni da fuocofuria ai nemici e perdendo calore ogni volta che li attraversa. (2 Min Recupero)\n[q2]Equipaggia: Gli attacchi in mischia hanno una probabilità di attivare gli ingranaggi del lanciatore, riducendone il tempo di recupero di 5 s e riscaldando l'arma, facendo sì che il successivo attacco infligga ( 1 * 23306 ) danni da fuoco aggiuntivi.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219302] = {name = "[q3]Sinfonia del Cantascarti", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Intelletto\n[q2]Equipaggia: Le abilità di cura hanno una probabilità di richiamare il metallo vicino, creando attorno a un alleato uno scudo che assorbe 45216 danni subiti.\n\n Lo scudo reagisce violentemente al fuoco, infliggendo 4162 danni da fuoco ai nemici vicini quando si viene colpiti.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219303] = {name = "[q3]Concrezione del Gran Oratore", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]+ 604 Maestria\n[q2]Usa: Carica il cristallo per evocare una fenditura che sottrae potere dai nemici vicini, infliggendo ( 1 * 45046 * 6) danni da ombra in 6 sec.\n\n Quando la fenditura collassa, l'energia torna indietro, aumentando l'Intelletto di 135 per 20 sec, aumentato ulteriormente per ogni nemico colpito. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219304] = {name = "[q3]Fischietto di Cera del Conduttore", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Agilità\n[q2]Equipaggia: Gli attacchi hanno una probabilità di dirigere un carretto dei Coboldi verso il bersaglio, inviando una truppa che si scontra con i nemici e infligge ( 1 * 50842 ) danni fisici suddivisi tra i nemici colpiti.\n[q]\"Il trofeo simbolico di un eroe, perché i Coboldi non hanno bisogno di essere evocati. I Coboldi bramano le catacombe.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219305] = {name = "[q3]Cera di Ardikon Intagliata", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Intelletto\n[q2]Equipaggia: Gli incantesimi hanno una probabilità di infondere la cera, trasformandola in una candela fiammeggiante che aumenta l'indice di versatilità di 1292 per 15 sec, ulteriormente aumentato di 136 finché si rimane all'interno della luce.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219306] = {name = "[q3]Bulino del Re delle Candele", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Intelletto\n[q2]Usa: Intaglia una copia di cera del bersaglio, che assorbe il 50 % dei danni subiti. L'assorbimento scalda la cera, che si scioglie dopo aver assorbito 264398 danni. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219307] = {name = "[q3]Residuo di Tenebra", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]Equipaggia: Le abilità hanno una probabilità di richiamare l'Oscurità, aumentando [<Primary Stat>] di 245 , fino a un massimo di ( 245 * 5).\n\n Quando raggiunge il pieno potere, l'Oscurità si scatena, infliggendo ( 1 * 19933 * 15 / 3) danni da ombra suddivisi tra i nemici vicini in 15 sec prima di tornare a essere un residuo.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219308] = {name = "[q3]Anello con Sigillo della Prioria", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 [Agilità o Forza o Intelletto]\n[q2]Usa: Alza l'anello con sigillo verso la Luce, aumentando la statistica secondaria più alta di 2756 per 20 sec. Il gesto ispira tutti i membri del gruppo vicini che hanno un anello con sigillo, fornendo loro 73 della stessa statistica per 20 sec. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219309] = {name = "[q3]Tomo della Devozione alla Luce", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]Equipaggia: Avanza ai 50 Versi di Resilienza Interiore, leggendoli mentre ti attaccano.\n Resilienza Interiore aumenta l'armatura di 934 e fornisce agli attacchi una probabilità di invocare uno scudo che assorbe 67723 danni magici subiti. Al termine, si passa a leggere un altro capitolo.\n\nValido solo per le specializzazioni da difensore. (750ms di recupero)\n[q2]Usa: Permette di sfogliare i passaggi nel tomo con maggiore Radiosità . (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219310] = {name = "[q3]Scheggialuce Esplosiva", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Intelletto\n[q2]Usa: Evoca un esemplare di Prole della Luce Ribollente che sacrifica la sua salute per scatenare Esplosioni di Luce, infliggendo 47520 danni da sacro suddivisi tra i nemici vicini ogni 2 s finché è vivo. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219311] = {name = "[q3]Pietra del Patto del Vuoto", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Forza\n[q2]Equipaggia: Gli attacchi hanno una probabilità di evocare il patto, infliggendo ( 1 * 24557 ) danni da ombra suddivisi tra i nemici vicini e aumentando l'indice di celerità di 377 per 10 sec.\n\n La tua morte annulla il patto, provocando una violenta esplosione.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219312] = {name = "[q3]Cristallo Potenziante di Anub'ikkaj", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 [Agilità o Intelletto]\n[q2]Equipaggia: Gli incantesimi e le abilità hanno una probabilità di rilasciare un potenziamento crescente dal cristallo, aumentando una statistica secondaria casuale di 1392 per 20 sec.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219313] = {name = "[q3]Rintocco di Mereldar", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Intelletto\n[q2]Usa: Rilascia un rintocco di luce sacra sul bersaglio, infliggendo ( 1 * 37459 ) danni da sacro. I successivi 5 alleati che attaccano il bersaglio ricevono la Benedizione di Mereldar, che ne aumenta l'indice di versatilità di 658 per 10 sec. (1 Min, 30 S Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219314] = {name = "[q3]Sacca della Stirpe di Ara-Kara", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]+ 604 Celerità\n[q2]Equipaggia: Le abilità hanno una probabilità di agitare la sacca, rilasciando un uovo che fornisce 213 [<Primary Stat>]. Ogni uovo si schiude dopo 1 min e la nuova stirpe attacca il bersaglio successivo, infliggendo ( 1 * 1109 * 8 / 1) danni da natura in 8 sec. (100ms di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219315] = {name = "[q3]Modulo d'Aggressione Rifrangente", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 [Agilità o Forza]\n[q2]Equipaggia: Le abilità di provocazione attivano l'energia rifrangente del modulo, proteggendoti dal 50 % dei danni subiti, fino a un massimo di 301603 . Può verificarsi solo una volta ogni 1 min.\n\nValido solo per le specializzazioni da difensore. (1m di recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219316] = {name = "[q3]Ghiandola di Sciame Incessante", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 [Agilità o Forza]\n[q2]Equipaggia: La ghiandola rilascia feromoni che attraggono uno Sciame Incessante di insetti tutt'intorno. Subire danni fornisce un'alta probabilità di contrattaccare gli attaccanti, infliggendo ( 1893 * 6 / 1) danni da natura in 6 sec e riducendo i danni subiti di 3438 .\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219317] = {name = "[q3]Editto del Mietitore", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 [Agilità o Intelletto]\n[q2]Equipaggia: Gli incantesimi e le abilità d'attacco hanno una probabilità di lanciare un globo di Sangue Nero instabile verso il bersaglio. All'impatto, il globo esplode, infliggendo ( 1 * 38832 ) danni da ombra suddivisi tra tutti i nemici vicini. Intercettare il lancio permette di assorbirne il potere, aumentando l'indice di maestria di 1653 per 15 sec.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219318] = {name = "[q3]Laringe dell'Oratore Opprimente", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n[q2]Equipaggia: Gli attacchi hanno una probabilità di smuovere la laringe, permettendo ai suoi oscuri sussurri di influenzarti. Ogni sussurro scorre nella tua mente per 30 sec, aumentando la Forza di 198 .\n[q2]Usa: Sventola la laringe in aria per scatenare un coro di tormenti, che infligge ( 1 * 58370 * 3 / 1) danni da ombra in 3 sec suddivisi tra i nemici vicini. I sussurri se ne vanno per unirsi al coro, aumentandone i danni subiti prima di diventare silenti. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219319] = {name = "[q3]Strumenti delle Zanne Gemelle", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Agilità\n[q2]Usa: Apre la borsa per tirarne fuori una delle lame di Nx e colpire rapidamente i nemici frontali, infliggendo ( 1 * 23075 ) danni da ombra a tutti i nemici colpiti.\n\n È possibile usare la borsa fino a 2 volte aggiuntive entro 20 sec, prima che si sigilli per ricaricare magicamente il contenuto. (2 Min Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219320] = {name = "[q3]Amalgama Coagulato Viscoso", additional_info = "Si vincola alla raccolta\nUnico equipaggiabile\nMonile\n+549 Intelletto\n[q2]Equipaggia: Le sovracure attraggono l'energia dell'ombra nelle vicinanze, accumulando fino a 8407 cure e rigenerando la salute del bersaglio quando subisce danni.\n[q2]Usa: Canalizza il potere dell'Amalgama Coagulato, dirigendo tutta l'energia d'ombra attuale per proteggere il bersaglio. (1 Min Recupero)\nPrezzo di vendita:"}
