MultiLanguageItemData['it'][219384] = {name = "[q2]Tenir e l'Ordine della Notte", additional_info = "Si vincola alla raccolta\nQuesto oggetto avvia una missione\n[q]\"Un'opera epica di dieci ore in tre atti.\""}
MultiLanguageItemData['it'][219385] = {name = "Siero Antiparalisi", additional_info = "Oggetto di missione\n[q2]Usa: Somministra il Siero Antiparalisi a un bersaglio paralizzato dalla fiasca del Marionettista.\n[q]\"Un siero per curare una paralisi. (Efficacia variabile).\""}
MultiLanguageItemData['it'][219386] = {name = "[q4]Locus della Potenza", additional_info = "Gemma Meta\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Apprendi il seguente incantesimo.\n\n Locus della Potenza\nCanalizza il potere arcano per 4 sec. Ogni 0.40 s, ti infonde assieme a 2 alleati entro 50 m, aumentando l'indice di celerità, di critico e di maestria per 30 sec.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo Meta.\""}
MultiLanguageItemData['it'][219387] = {name = "[q3]Barili di Fuochi d'Artificio", additional_info = "Giocattolo\n[q2]Usa: Piazza un pericoloso Barile di Fuochi d'Artificio per 5 min, in modo che tu e i tuoi amici possiate illuminare il cielo notturno!\n\n Anche gli altri giocatori possono godersi i fuochi d'artificio attaccando il barile.\n\n Tempo di recupero ridotto durante le baldorie dei Goblin ubriachi. (1 Ora Recupero)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219388] = {name = "Torcia della Fiamma Sacra", additional_info = "Oggetto di missione\n[q2]Usa: Raduna un gruppo di Arathi che credono nella Fiamma Sacra!\n[q]\"La torcia brucia con la Luce, il suo crepitare sembra quasi una canzone.\""}
MultiLanguageItemData['it'][219389] = {name = "[q2]Parafulmine", additional_info = "Gemma Modifica\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Le abilità hanno una probabilità di applicare Parafulmine al bersaglio. L'effetto aumenta l'indice di critico degli alleati per 10 sec e infligge danni da natura ai nemici ogni 2 s per 8 sec. Al termine, il Parafulmine torna a chi l'ha lanciato, aumentandone l'indice di critico per 10 sec.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo per Modifica.\""}
MultiLanguageItemData['it'][219390] = {name = "[q3]Impostazione Mappa Chiave del Potere: Grim Batol", additional_info = "Durata: 12 ore (tempo reale)\n[q2]Usa: Imposta Grim Batol come mappa di una Chiave del Potere.\nPrezzo di vendita:"}
MultiLanguageItemData['it'][219391] = {name = "[q4]Dirigibile delle Scorribande", additional_info = "[q7]Si vincola alla Brigata\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda il tuo Dirigibile delle Scorribande.\n\n Questa cavalcatura può usare Viaggio in Compagnia.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questo velivolo ti aiuterà a tuffarti dritto all'avventura, ovunque essa sia!\"\nMissione:\nAll'avventura!\nZona:\nIsola di Dorn"}
