MultiLanguageItemData['it'][220120] = {name = "[q4]Legame d'Anima", additional_info = "Gemma Meta\nSi vincola alla raccolta\nUnico\n[q2]Equipaggia: Apprendi il seguente incantesimo.\n\n Legame d'Anima\nLega l'anima a quella di un alleato per 1 hour, reindirizzando il 20% dei danni da lui subiti verso di te sotto forma di danni da ombra. L'effetto può essere usato su massimo 5 alleati. Rilanciare l'effetto su un alleato già legato o allontanarsi di oltre 100 m dissolve l'effetto.\nRichiede dal livello 10 al 70 ( 70)\n[q]\"Compatibile con un incavo Meta.\""}
MultiLanguageItemData['it'][220122] = {name = "Offerta di Acqua Pura", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Combina l'Offerta di Acqua Pura e il Vaso di Muco.\n[q]\"Non c'è impurità nell'acqua cristallina. È possibile vedere attraverso il vetro come se non ci fosse nient'altro dentro.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][220123] = {name = "Offerta Inquietante", additional_info = "Si vincola alla raccolta\n[q2]Usa: Inizia un rituale inquietante.\n[q]\"Anche se traboccante di potere, sembra che manchi ancora un componente cruciale.\""}
MultiLanguageItemData['it'][220124] = {name = "Vaso di Muco", additional_info = "Si vincola alla raccolta\nUnico\n[q2]Usa: Combina l'Offerta di Acqua Pura e il Vaso di Muco.\n[q]\"Una fonte di energia disgustosa ma potente, ottima per i rituali necromantici.\"\nPrezzo di vendita:"}
