MultiLanguageItemData['it'][221903] = {name = "[q2]Prototipo: Modifica: Trivella da Consegna dei Terrigeni", additional_info = "Si vincola alla raccolta\nUnico: Prototipo (1)\n[q2]Usa: Evoca una Trivella da Consegna dei Terrigeni che fornisce un assortimento di benefici per il campo di battaglia.\n\n La trivella dura 28 sec e può essere evocata solo in combattimento. utilizzabile solo nei campi di battaglia non classificati e in modalità Guerra a Khaz Algar. (15 Min Recupero)\nRichiede Ingegneria di Khaz Algar (1)\nPrezzo di vendita:"}
MultiLanguageItemData['it'][221907] = {name = "[q2]Prototipo: Modifica: Iniettore di Salute Centracuori", additional_info = "Si vincola alla raccolta\nUnico: Prototipo (1)\n[q2]Usa: Inietta una formula di fuocogelo medicinale nelle vene, rigenerando istantaneamente fino a 1943637 salute grazie alla scarica di freddo. Per evitare l'ipotermia, poi si brucia il 30 % delle cure ricevute.\n\n Condivide il tempo di recupero con le pozioni di cura.\nRichiede Ingegneria di Khaz Algar (1)\nPrezzo di vendita:"}
