MultiLanguageItemData['it'][223264] = {name = "[q4]Acaro Sciamante d'Acquamarina", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 23 con i Fili Recisi. Richiede il livello di Fama 22 con i Fili Recisi.\n\n\n[q]\"Benché non siano molto comuni, i rappresentanti dei Fili Recisi assicurano che gli acari sciamanti sono più che capaci di reggere il tuo peso, se dovessi decidere di usarne uno come cavalcatura.\"\nMercante:\nDama Vinazian\nZona:\nAzj-Kahet\nCosto:\n3.940\n\nMercante:\nY'tekhi\nZona:\nAzj-Kahet\nCosto:\n3.940"}
MultiLanguageItemData['it'][223266] = {name = "[q4]Redini dell'Acaro Sciamante Adombrato", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Gli Acari Sciamanti sono comuni sia nelle selve di Azj-Kahet che tra i Nerubiani che li hanno addomesticati da tempo, ma ciò non li rende meno pericolosi per gli avventurieri incauti.\"\nImpresa:\nGloria dell'incursore dei Nerub'ar\nCategoria:\nSpedizioni e incursioni"}
MultiLanguageItemData['it'][223267] = {name = "[q4]Acaro Sciamante Predacieli", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Di solito presente negli anfratti più nascosti dei soffitti rocciosi, l'Acaro Sciamante Predacieli è più a suo agio nell'aria che a riposo.\"\nImpresa:\nCacciatore di glifi a Khaz Algar\nCategoria:\nThe War Within"}
MultiLanguageItemData['it'][223269] = {name = "[q4]Unità di Difesa della Macchina 1-11", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Una delle tante meccanotute progettate per proteggere la Macchina. Dopo anni di fedele servizio, non è più adatta al combattimento. Però come mezzo di trasporto fa un figurone.\"\nTesoro:\nCassa Risvegliata\nZona:\nProfondità Risonanti"}
MultiLanguageItemData['it'][223270] = {name = "[q4]Alunira", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"La quintessenza delle nuvole è rimasta a lungo intrappolata sulla cima di una montagna di fulmini. Finalmente posso nuovamente sentire il vento sul mio borso.\"\nBottino:\nZona:\nIsola di Dorn"}
MultiLanguageItemData['it'][223274] = {name = "[q4]Strisciafauci Feroce", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di Fama 22 con i Fili Recisi. Richiede il livello di Fama 17 con i Fili Recisi.\n\n\n[q]\"Questo strisciafauci particolarmente grande è delle dimensioni perfette per fungere da cavalcatura... però tieni le mani lontano dalla sua bocca.\"\nMercante:\nDama Vinazian\nZona:\nAzj-Kahet\nCosto:\n2.815\n\nMercante:\nY'tekhi\nZona:\nAzj-Kahet\nCosto:\n2.815"}
MultiLanguageItemData['it'][223276] = {name = "[q4]Strisciafondo della Vedova", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di reputazione Cospiratore con la Tessitrice.\n\n\n[q]\"I bambini della superficie spesso esprimono il desiderio di avere un pony o un lupo tutto loro quando raggiungono certe età. Una giovane Vedova Arak'nai aveva ambizioni simili, anche se i suoi gusti sarebbero probabilmente considerati eclettici secondo alcuni standard.\"\nMercanti:\nYamas la Fornitrice, Bobina\nZona:\nAzj-Kahet\nCosto:\n2.020"}
MultiLanguageItemData['it'][223278] = {name = "[q4]Strisciafondo del Retaggio", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di reputazione Cospiratore con il Generale.\n\n\n[q]\"L'allevamento di aracnidi è una lunga tradizione tra le Forze del Retaggio. Sebbene alcuni esemplari vengano usati come animali da soma o addestrati come truppe d'assalto, i migliori della loro stirpe finiscono talvolta per diventare cavalcature da parata.\"\nMercanti:\nYamas la Fornitrice, Anub'okki, Pretendente Kiipka\nZona:\nAzj-Kahet\nCosto:\n2.020"}
MultiLanguageItemData['it'][223279] = {name = "[q4]Strisciafondo della Corte Reale", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nRichiede il livello di reputazione Cospiratore con il Visir.\n\n\n[q]\"I pedigree vengono usati per demarcare la storia e il valore degli strisciafondo purosangue nell'alta società dei Kaheti. Questa pratica può rivelarsi alquanto difficile quando i suddetti strisciafondo sono inclini a consumare improvvisamente chi custodisce questi documenti.\"\nMercanti:\nYamas la Fornitrice, Tulumun\nZona:\nAzj-Kahet\nCosto:\n2.020"}
