MultiLanguageItemData['it'][224147] = {name = "[q4]Redini dello Sferzacieli Sureki", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Lo sferziacieli è uno degli abomini più feroci mai emersi dagli esperimenti della Regina Ansurek con il Sangue Nero degli Dei Antichi.\"\nBottino:\nRegina Ansurek\nZona:\nPalazzo dei Nerub'ar"}
MultiLanguageItemData['it'][224150] = {name = "[q4]Siesbarg", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Poverino.\"\nMissione Mondiale:\nVolo di consolazione\nZona:\nAzj-Kahet\nZona:\nCittà dei Fili"}
MultiLanguageItemData['it'][224151] = {name = "[q4]Redini dello Sferzacieli Asceso", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Pensati per i più devoti tra l'élite dei Sureki, questi sferzacieli erano i preferiti della Regina Ansurek sia per astuzia che per brutalità.\"\nBottino:\nRegina Ansurek\nZona:\nPalazzo dei Nerub'ar (Mitica)"}
