MultiLanguageItemData['it'][224811] = {name = "[q3]Funghi di Zucchero", additional_info = "Si vincola alla raccolta\nUnico (20)\n[q2]Usa: L'essenza fungina plasma la tua forma e aumenta la celerità del 25% per 30 sec.\n\n Utilizzabile presso Fioritura della Luce e nelle zone delle Guardafiamme vicine. (30 S Recupero)\nRichiede il livello di Fama 12 con gli Arathi dei Precipizi Sacri.[q]\"I bambini adorano andare alla ricerca di queste delizie dolci!\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][224813] = {name = "[q3]Fischietto del Grande Felino", additional_info = "Si vincola alla raccolta\nUnico (20)\n[q2]Usa: Evoca una grossa lince da battaglia che aiuta in combattimento per 5 min.\n\n Utilizzabile presso Fioritura della Luce e nelle zone delle Guardafiamme vicine. (5 Min Recupero)\nRichiede il livello di Fama 12 con gli Arathi dei Precipizi Sacri.[q]\"La più grande delle linci è a un fischio di distanza.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][224814] = {name = "[q4]Stivali Vincolati alla Brigata dell'Avventuriero", additional_info = "[q7]Si vincola alla Brigata\n[q2]Usa: Crea un pezzo per piedi per la tua classe.\nSi sblocca coi progressi nella Stagione 1 dei Viaggi nelle Scorribande.\n[q]\"Contiene un pezzo d'equipaggiamento dell'Avventuriero 4/8 per la tua classe.\""}
MultiLanguageItemData['it'][224815] = {name = "[q3]Talismano della Fiamma", additional_info = "Si vincola alla raccolta\nUnico (20)\n[q2]Usa: L'infusione con la fiamma sacra fa sì che gli attacchi e le abilità facciano comparire talvolta un Elementale di luce, che infligge 3 danni da sacro ai bersagli.\n\n Utilizzabile presso Fioritura della Luce e nelle zone delle Guardafiamme vicine.\nRichiede il livello di Fama 12 con gli Arathi dei Precipizi Sacri.[q]\"La disponibilità in calo di questi oggetti si sta rapidamente esaurendo presso gli Arathi.\"\nPrezzo di vendita:"}
