MultiLanguageItemData['it'][225250] = {name = "[q4]Sofficiotto Astrale", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda il Sofficiotto Astrale.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Uno dei primi viandanti eterni incontrò i sofficiotti e fece amicizia con una coppia di questi animali. Riaccompagnando il viandante nel suo dominio, i felini furono cambiati per sempre dalla vita in quel luogo e dalla compagnia dei viandanti.\"\nNegozio di gioco"}
MultiLanguageItemData['it'][225251] = {name = "[q2]Smontaggio Invenzione", additional_info = "[q]\"Smonta un'invenzione indesiderata per recuperare alcune parti di riciclo e studiarne il funzionamento interno.\""}
