MultiLanguageItemData['it'][226505] = {name = "[q4]Tessigemme Nerubiano", additional_info = "Si vincola alla raccolta\n[q2]Usa: Aggiunge un incavo a un oggetto della Stagione 1 di The War Within che non ne ha già uno. Può essere usato su pezzi per testa, polsi o fianchi. Non utilizzabile su equipaggiamenti PvP."}
MultiLanguageItemData['it'][226506] = {name = "[q4]Mano di Reshkigaal", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Reshkigaal temporeggiò mentre i suoi simili provavano a usurpare l'Esiliato. Provò ad attaccare mentre era distratto, ma le spie del Carceriere la stavano pedinando. Con il loro avvertimento e aiuto, il Carceriere ebbe la meglio.\"\nEmporio"}
MultiLanguageItemData['it'][226507] = {name = "Sfregatele del Dahn dei Veleni", additional_info = "Si vincola alla raccolta\n[q2]Usa: Strofinarsi con il veleno degli artropodi permette di rimuovere 1 accumulo di Marchio dell'Eradicatore.\nRichiede il livello di reputazione Socio con il Generale.[q]\"Uno scrub per il corpo a base di veleno utile per rimuovere la sporcizia e gli accumuli di ragnatela dai Marchi dell'Eradicatore. Ingredienti naturali all'88%!\""}
MultiLanguageItemData['it'][226508] = {name = "Influenza del Visir", additional_info = "Si vincola alla raccolta\n[q2]Usa: Permette di corrompere i Nerubiani giusti.\n\n La volta successiva che si viene espulsi dalla Città dei Fili da una guardia, si torna invece dallo Speziale Reale. L'effetto persiste per 60 min.\nRichiede il livello di reputazione Complice con il Visir.[q]\"Un set di documenti \"ufficiali\", con cui \"incoraggiare\" le guardie della Città dei Fili a reindirizzarti dallo Speziale Reale in caso di cattura.\""}
MultiLanguageItemData['it'][226509] = {name = "Consapevolezza del Generale", additional_info = "Si vincola alla raccolta\n[q2]Usa: Permette di visualizzare il raggio di individuazione delle guardie della Città dei Fili per 10 min.\n\n Hai imparato molto dal Generale.\nRichiede il livello di reputazione Complice con il Generale.[q]\"Una copia dei documenti con le pattuglie e i metodi dei Sureki. Permette di vedere il raggio d'individuazione di tutte le guardie nella Città dei Fili.\""}
MultiLanguageItemData['it'][226510] = {name = "Facciata della Tessitrice", additional_info = "Si vincola alla raccolta\n[q2]Usa: Permette di assumere l'aspetto di un vero Nerubiano, riducendo il raggio d'individuazione delle guardie della Città dei Fili per 1 min.\n\n La Tessitrice è una maestra dei travestimenti.\nRichiede il livello di reputazione Complice con la Tessitrice.[q]\"Una mistura di feromoni in grado di confondere le guardie della Città dei Fili, riducendone significativamente il raggio d'individuazione. Una specialità della Tessitrice.\""}
MultiLanguageItemData['it'][226511] = {name = "Intruglio di Nerubimorfosi", additional_info = "Si vincola alla raccolta\n[q2]Usa: Permette di lanciare un intruglio che trasforma una guardia della Città dei Fili in un essere meno minaccioso per 30 s.\n\n Una mistura speciale creata dal Visir in persona.\nRichiede il livello di reputazione Socio con il Visir. Richiede il livello di reputazione Socio con la Tessitrice.[q]\"Una miscela lanciabile che trasforma le vittime in innocue tessispie per un breve periodo. Funziona solo sulle guardie della Città dei Fili.\""}
MultiLanguageItemData['it'][226512] = {name = "Mappa del Tesoro: Memoriale Dimenticato", additional_info = "Si vincola alla raccolta\nUnico (5)\n[q2]Usa: Rivela la posizione del Memoriale Dimenticato sulla tua mappa.\nRichiede il livello di reputazione Socio con il Generale."}
MultiLanguageItemData['it'][226513] = {name = "Mappa del Tesoro: Scavi dei Kaheti", additional_info = "Si vincola alla raccolta\nUnico (5)\n[q2]Usa: Rivela la posizione degli Scavi dei Kaheti sulla tua mappa.\nRichiede il livello di reputazione Socio con il Visir."}
MultiLanguageItemData['it'][226514] = {name = "Mappa del Tesoro: Cassa delle Tessispie", additional_info = "Si vincola alla raccolta\nUnico (5)\n[q2]Usa: Rivela la posizione della Cassa delle Tessispie sulla tua mappa.\nRichiede il livello di reputazione Socio con la Tessitrice."}
MultiLanguageItemData['it'][226515] = {name = "Mappa delle Voci: Taglie", additional_info = "Si vincola alla raccolta\nUnico (5)\n[q2]Usa: Rivela la posizione delle Voci sulle Taglie sulla tua mappa."}
MultiLanguageItemData['it'][226516] = {name = "Mappa delle Voci: Disgregazione", additional_info = "Si vincola alla raccolta\nUnico (5)\n[q2]Usa: Rivela la posizione delle Voci sulla Disgregazione sulla tua mappa."}
MultiLanguageItemData['it'][226517] = {name = "Mappa delle Voci: Spionaggio", additional_info = "Si vincola alla raccolta\nUnico (5)\n[q2]Usa: Rivela la posizione delle Voci di Spionaggio sulla tua mappa."}
MultiLanguageItemData['it'][226518] = {name = "Ferofuga", additional_info = "Si vincola alla raccolta\n[q2]Usa: Permette di lanciare un'implosione di vari feromoni che stordiscono le guardie della Città dei Fili per 2 s, interrompendo il combattimento.\nRichiede il livello di reputazione Socio con il Visir.[q]\"Lancia questa implosione di feromoni per stordire i nemici e uscire dal combattimento. Funziona solo sulle guardie della Città dei Fili.\""}
MultiLanguageItemData['it'][226519] = {name = "[q3]Perizia del Generale", additional_info = "Si vincola alla raccolta\nGiocattolo\n[q2]Usa: Permette di visualizzare il raggio di individuazione delle guardie della Città dei Fili.\n\n Hai imparato molto dal Generale.\nRichiede il livello di reputazione Socio con la Tessitrice, il Generale o il Visir.[q]\"Una copia trascritta del manuale di combattimento su cui studiano tutti i soldati di Azj-Kahet. Attivarlo ti consente di vedere il raggio d'individuazione di tutte le guardie della Città dei Fili.\""}
MultiLanguageItemData['it'][226520] = {name = "Feromoni della Regina", additional_info = "Si vincola alla raccolta\n[q2]Usa: Fornisce i feromoni della Regina.\n\n Le guardie della Città dei Fili non interferiscono con i tuoi affari.\nRichiede il livello di reputazione Orchestratore con la Tessitrice, il Generale o il Visir.[q]\"Con i feromoni della Regina ottenuti con discrezione. Le guardie della Città dei Fili non saranno più in grado di individuarti.\""}
