MultiLanguageItemData['it'][229193] = {name = "Feromoni della Regina", additional_info = "Si vincola alla raccolta\n[q2]Usa: Fornisce i feromoni della Regina.\n\n Le guardie della Città dei Fili non interferiscono con i tuoi affari.\n[q]\"I feromoni della Regina, ottenuti con discrezione, permettono di non essere individuati dalle guardie della Città dei Fili.\""}
