MultiLanguageItemData['it'][229196] = {name = "Disegno di Bakar", additional_info = "Segreti di Azeroth\nOggetto di missione\n[q]\"L'avrà disegnato e lasciato qui qualche aspirante artista. Il disegno rappresenta un piccolo bakar.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][229198] = {name = "Asso di Aria", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una mano che emerge da una nuvola, mentre afferra una spada circondata da una corona.\""}
MultiLanguageItemData['it'][229199] = {name = "Due di Aria", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una figura bendata che tiene in equilibrio due burrasche sulle spalle.\""}
MultiLanguageItemData['it'][229200] = {name = "Tre di Aria", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta tre raffiche di forte vento che trafiggono un cuore, con nubi tempestose e pioggia sullo sfondo.\""}
MultiLanguageItemData['it'][229201] = {name = "Quattro di Aria", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta l'effigie di un cavaliere in preghiera su quella che è presumibilmente la sua tomba.\""}
MultiLanguageItemData['it'][229202] = {name = "Cinque di Aria", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta un uomo sprezzante e accigliato verso due figure avvilite che si ritirano dopo aver lasciato i loro sacchi d'aria per terra. L'uomo porta altri due sacchi sulla spalla sinistra e un terzo nella mano destra.\""}
MultiLanguageItemData['it'][229203] = {name = "Sei di Aria", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta un traghettatore che trasporta alcuni passeggeri sulla propria imbarcazione fino all'altra sponda. La rotta è senza ostacoli e, dato il carico leggero, è evidente che questo lavoro non rappresenta una sfida particolare.\""}
MultiLanguageItemData['it'][229204] = {name = "Sette di Aria", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una persona nell'atto di portar via rapidamente cinque venti. Altri due sono per terra, e nelle vicinanze c'è un accampamento.\""}
MultiLanguageItemData['it'][229205] = {name = "Otto di Aria", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta un prigioniero bendato, circondato da otto venti tempestosi. Eppure, si tratta di una prigionia temporanea, piuttosto che una irrimediabile.\""}
MultiLanguageItemData['it'][229206] = {name = "Asso di Fuoco", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una mano che emerge da una palla di fuoco ardente, mentre afferra una bacchetta avvolta dal fumo.\""}
MultiLanguageItemData['it'][229207] = {name = "Due di Fuoco", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta un'alta figura che guarda dal tetto di un bastione affacciato sul mare. Regge una sfera nella mano destra e un bastone ardente nella sinistra, che poggia sul bastione. Un altro bastone ardente è fissato a un anello alla destra della figura.\""}
MultiLanguageItemData['it'][229208] = {name = "Tre di Fuoco", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una figura calma e maestosa, di spalle, che guarda dal limitare di una scogliera le navi che scivolano sul mare. Nel terreno sono piantati tre bastoni, ognuno dei quali regge una lanterna, mentre la figura si appoggia leggermente a uno di essi.\""}
MultiLanguageItemData['it'][229209] = {name = "Quattro di Fuoco", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta quattro grandi pilastri in primo piano, con una ghirlanda di puro fuoco sospesa tra di loro. Due figure reggono dei fiori profumati e al loro fianco si trova un ponte sopra un fossato che conduce a un vecchio maniero.\""}
MultiLanguageItemData['it'][229210] = {name = "Cinque di Fuoco", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta un gruppo di cinque giovani che brandiscono dei bastoni come per giocare. È la finzione di una battaglia, e i loro occhi bruciano di fuoco.\""}
MultiLanguageItemData['it'][229211] = {name = "Sei di Fuoco", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una figura a cavallo adornata da una corona d'alloro e con in mano una spada fiammeggiante. Cinque fanti con spade fiammeggianti simili sono al suo fianco.\""}
MultiLanguageItemData['it'][229212] = {name = "Sette di Fuoco", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una figura caparbia in piedi su una collina accidentata, che tiene sollevata una torcia. Altre sei torce vengono sollevate verso la figura dal basso.\""}
MultiLanguageItemData['it'][229213] = {name = "Otto di Fuoco", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una raffica di otto frecce infuocate che solcano i cieli mentre si avvicinano alla fine della loro traiettoria. Il loro significato è imminente, quasi a portata di mano.\""}
MultiLanguageItemData['it'][229214] = {name = "Asso di Gelo", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una mano che emerge dal terreno ricoperto di neve fresca, mentre stringe lo stelo di un calice pieno fino a traboccare di acqua fumante.\""}
MultiLanguageItemData['it'][229215] = {name = "Due di Gelo", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta due giovani in piedi in una scena invernale, che brindano tra loro con boccali di ghiaccio purissimo.\""}
MultiLanguageItemData['it'][229216] = {name = "Tre di Gelo", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta persone che festeggiano ballando in un giardino con le coppe sollevate come se si stessero promettendo qualcosa. La neve soffice cade tutt'intorno.\""}
MultiLanguageItemData['it'][229217] = {name = "Quattro di Gelo", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una figura avvolta da pellicce, seduta sotto un pino, che contempla tre calici adagiati nella neve davanti a sé. Un braccio che fuoriesce da una nuvola offre alla figura un quarto calice. La sua espressione tradisce malcontento.\""}
MultiLanguageItemData['it'][229218] = {name = "Cinque di Gelo", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una figura scura, ammantata, che guarda di lato verso tre coppe rovesciate in pozze d'acqua. Altre due coppe sono in piedi dietro la figura, su piedistalli di ghiaccio. Sullo sfondo, un ponte conduce a una piccola fortezza.\""}
MultiLanguageItemData['it'][229219] = {name = "Sei di Gelo", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta dei bambini in un vecchio giardino che annaffiano i fiori con delle coppe piene di neve sciolta.\""}
MultiLanguageItemData['it'][229220] = {name = "Sette di Gelo", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta strane visioni che sgorgano da sette calici fatti del ghiaccio più puro, ma sono immagini di uno spirito fantastico.\""}
MultiLanguageItemData['it'][229221] = {name = "Otto di Gelo", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una figura avvilita che vaga in giro, lasciando dietro di sé le coppe contenenti la sua fortuna, le sue imprese, il suo impegno o le sue preoccupazioni precedenti, che vengono tutte inghiottite dal ghiaccio.\""}
MultiLanguageItemData['it'][229222] = {name = "Asso di Terra", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una mano che emerge da un terreno roccioso in una nuvola di polvere mentre sostiene un disco di pietra.\""}
MultiLanguageItemData['it'][229223] = {name = "Due di Terra", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta un bambino nell'atto di ballare con un disco di pietra in ciascuna mano. I dischi sono uniti da una corda infinita, che disegna il numero 8 ruotato.\""}
MultiLanguageItemData['it'][229224] = {name = "Tre di Terra", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta uno scultore al lavoro in un monastero. L'apprendista ha ricevuto la sua ricompensa e ora lavora con impegno.\""}
MultiLanguageItemData['it'][229225] = {name = "Quattro di Terra", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una figura incoronata con un disco di pietra sopra la testa, che stringe un altro disco con le braccia e tiene altri due dischi sotto i piedi. Una persona aggrappata a ciò che ha.\""}
MultiLanguageItemData['it'][229226] = {name = "Cinque di Terra", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta due mendicanti in una tempesta di polvere mentre passano davanti a una finestra illuminata da cinque dischi di pietra luminosi.\""}
MultiLanguageItemData['it'][229227] = {name = "Sei di Terra", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta una persona vestita da mercante che pesa il denaro su una bilancia e poi lo distribuisce ai bisognosi e agli afflitti. È una testimonianza del suo successo nella vita e della sua bontà d'animo.\""}
MultiLanguageItemData['it'][229228] = {name = "Sette di Terra", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta un adolescente, appoggiato al suo bastone, che guarda intensamente sette dischi di pietra attaccati a un ciuffo di vegetazione alla sua destra. Si potrebbe dire che si tratti di tesori e che il cuore del giovane si trovi lì con loro.\""}
MultiLanguageItemData['it'][229229] = {name = "Otto di Terra", additional_info = "Mazzo della Fortuna di Lunacupa\n[q]\"Rappresenta un artista della pietra al lavoro, che espone i propri lavori sotto forma di trofei.\""}
MultiLanguageItemData['it'][229348] = {name = "[q4]Chiavi di Incognitro, l'Indecifrabile Vilmoto", additional_info = "Si vincola alla raccolta\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare Incognitro, l'Indecifrabile Vilmoto.\n[q2]Evoca e congeda una motocicletta alimentata a potere demoniaco.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questo marchingegno demoniaco è stato progettato dal Capo Ingegnere Ulzik come esperimento per attraversare le dimensioni. Nonostante le numerose morti durante i test, Ulzik era convinto che questo veicolo avrebbe rivelato i segreti ancora sconosciuti dell'universo.\"\nEvento mondiale:\n20° Anniversario di WoW?"}
