MultiLanguageItemData['it'][232991] = {name = "[q4]Canto del Demolitore", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda il Canto del Demolitore.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"È un momento raro, quello in cui un marinaio scolpisce sulla prua della sua nave il mostro che lo ha lasciato sulla spiaggia a morire. Siamo un'accozzaglia blasfema e insignificante. Pensare che uno di noi possa avere l'umiltà di onorare una simile creatura è quasi una follia.\"\nZona:\nIsola delle Sirene\nImpresa:\nUn'isola di ricordi"}
MultiLanguageItemData['it'][233013] = {name = "Biscotti di Carbone", additional_info = "Si vincola alla raccolta\n[q2]Usa: Rigenera ( 472500 / 5 * 25) salute e ( 630000 / 5 * 25) mana in 25 sec. Devi sederti per mangiare."}
MultiLanguageItemData['it'][233014] = {name = "[q4]Cassa di Tesori della Celebrazione di Bronzo", additional_info = "Si vincola alla raccolta\n[q]\"Cassa settimanale contenente materiali per potenziare l'equipaggiamento, oro e altro ancora.La prima cassa settimanale ottenuta ogni settimana contiene un pezzo di equipaggiamento del Campione dei Sotterranei di Roccianera e una Chiave dello Scrigno Ripristinata. Le casse seguenti contengono un pezzo di equipaggiamento del Veterano.\"\n[q2]<Destra Aprire>"}
