MultiLanguageItemData['it'][233240] = {name = "[q4]Polly Roger", additional_info = "[q7]Si vincola alla Brigata\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\n\n Questa cavalcatura può usare Viaggio in Compagnia.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"I pappagalli giganti come Polly, flagelli dei mari medio-nordorientali, possono vivere fino a 2.000 anni. Che meravigliosa maledizione per i tuoi discendenti.\"\nEvento speciale:\nPlunderstorm"}
MultiLanguageItemData['it'][233241] = {name = "[q4]Zampa d'Uncino", additional_info = "[q7]Si vincola alla Brigata\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\n[q2]Evoca e congeda questa cavalcatura.\n\n Questa cavalcatura può usare Viaggio in Compagnia.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"Un tempo Zampa d'Uncino navigava con i Bucanieri Velerosse, poi ha salpato con gli Incursori di Acquanera, ma se n'è andato per vedere che bottino si poteva trovare oltre il mare aperto.\"\nEvento speciale:\nPlunderstorm"}
MultiLanguageItemData['it'][233242] = {name = "[q4]Piumarina Reale", additional_info = "[q7]Si vincola alla Brigata\nUnico\nCavalcatura\n[q0](Vincolato all'account)\n[q2]Usa: Ti insegna a evocare questa cavalcatura.\nEvoca e congeda un Pappagallo Gigante, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\nPrezzo di vendita:\n[q]\"I becchi affilati di questi pappagalli possono spaccare le noci con facilità.\"\nEvento speciale:\nPlunderstorm"}
