MultiLanguageItemData['it'][234716] = {name = "[q4]Redini del Razziacieli di Notte Fonda", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nEvoca e congeda un Razziacieli di Notte Fonda, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Data la loro abitudine di calare sulle prede nel cuore della notte, un tempo i versi di questi razziacieli incutevano terrore in tutti i bambini di Draenor.\"\nMercante:\nKronnus\nZona:\nLancia da Guerra\nCosto:\n5.000\n\nMercante:\nTempah\nZona:\nScudo del Vento\nCosto:\n5.000"}
MultiLanguageItemData['it'][234718] = {name = "[q0]Elsa Runica Antica", additional_info = "[q]\"Sull'elsa vi è inciso il volto di una figura femminile con delle scritte runiche.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][234719] = {name = "[q0]Avambracci Incisi con Tempesta", additional_info = "[q]\"Sul bracciale vi è inciso il disegno di una cima tempestosa.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][234720] = {name = "[q0]Residuo Memorico", additional_info = "[q]\"La sostanza, simile a una polvere dorata, ha un aspetto sia spettrale che concreto.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][234721] = {name = "[q4]Briglie dello Squartacarne Ur'zul", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda il tuo Squartacarne Ur'zul.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Questo terrificante Ur'zul incorpora in sé le sue ultime vittime, creando un mostro pressoché inarrestabile. Meno male che lo tratti bene, altrimenti potresti diventare il suo prossimo spuntino.\"\nMercante:\nAridormi\nZona:\nDalaran\nCosto:\n5.000"}
MultiLanguageItemData['it'][234722] = {name = "[q0]Frammento di Pietra Intagliato", additional_info = "[q]\"Il frammento di pietra è tutto ciò che resta di un'antica costruzione in pietra.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][234723] = {name = "[q0]Sigillo Vuoto", additional_info = "[q]\"Delle incisioni sbiadite circondano il castone ormai vuoto al centro del sigillo.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][234730] = {name = "[q4]Progenie di Sinestra", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\n[q2]Evoca e congeda una Progenie di Sinestra cavalcabile, una cavalcatura volante.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Dopo la caduta del Bastione del Crepuscolo, dei Draghetti del Crepuscolo riuscirono a sfuggire all'influenza di Vexiona. Alcuni di questi si sono alleati con i mortali e sono disposti a far loro da destrieri.\"\nMercante:\nKiatke\nZona:\nRoccavento\nZona:\nOrgrimmar\nCosto:\n5.000"}
MultiLanguageItemData['it'][234732] = {name = "[q0]Medaglione Insanguinato", additional_info = "[q]\"Preziosi per i Vegliasangue, questi medaglioni vengono indossati solo da coloro che hanno ottenuto le loro prime cento sanguinose vittorie.\"\nPrezzo di vendita:"}
