MultiLanguageItemData['it'][234735] = {name = "[q0]Lanterna Rovinata dei Vrykul", additional_info = "[q]\"Anche il più coraggioso dei Vrykul si rifiuta di inoltrarsi in mare aperto senza la propria lanterna, che tiene lontana l'oscurità sotto le onde.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][234736] = {name = "[q0]Pergamena Sigillata con la Pece", additional_info = "[q]\"La mappa marittima all'interno mostra le rotte navali dei Vegliasangue e le numerose isole che assediano. Stranamente, l'Isola delle Sirene è contrassegnata da un indicatore di pericolo.\"\nPrezzo di vendita:"}
MultiLanguageItemData['it'][234740] = {name = "[q4]Redini del Quilen dal Manto Ramato", additional_info = "Si vincola alla raccolta\nCavalcatura\n[q0](Vincolato all'account)\nUsa: Ti insegna a evocare questa cavalcatura, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nEvoca e congeda un Quilen dal Manto Ramato, la cui velocità dipende da dove ti trovi e dalla tua competenza in Equitazione.\nRichiede dal livello 1 al 80 ( 80)\nRichiede Apprendista in Equitazione\n\n\n[q]\"Allevate nelle scuderie di Qon il Tenace, queste cavalcature sono ardentemente risolute e non abbandonano mai la loro posizione, nemmeno quando avvertirono la rovina dei loro padroni.\"\nMercante:\nTeurga del Misticismo Xia\nZona:\nIsola Senza Tempo\nCosto:\n5.000"}
